RV_LOAD("SMIS",{"lang": "DE", "stale": {"files": [], "anchors": []}, "hub": "用统计模型解决语言歧义: 从语料数频率, 估概率, 选最可能的分析.", "branches": [{"id": "korp", "zh": "语料与搭配", "de": "Korpus & Kollokation", "one": "从语料里数出频率, 再用检验判断词的组合是不是偶然.", "a0": -1.9284, "a1": -1.2132}, {"id": "prob", "zh": "概率基础", "de": "Wahrscheinlichkeit", "one": "后面所有模型都靠条件概率、链式法则、贝叶斯定理和相对频率估计.", "a0": -1.1132, "a1": -0.398}, {"id": "info", "zh": "信息论", "de": "Information", "one": "用熵度量不确定性, 也用交叉熵比较语言模型.", "a0": -0.298, "a1": 0.298}, {"id": "lm", "zh": "语言模型", "de": "Sprachmodelle", "one": "给词序列或字符序列一个概率, 并处理没见过的事件.", "a0": 0.398, "a1": 1.1132}, {"id": "tag", "zh": "分类与标注", "de": "Klassifikation & Tagging", "one": "朴素贝叶斯给单个词选词义, HMM 给整句选词性序列.", "a0": 1.2132, "a1": 1.9284}, {"id": "parse", "zh": "统计句法分析", "de": "Statistisches Parsen", "one": "给分析树概率, 选最可能的树, 并细化文法.", "a0": 2.0284, "a1": 2.7436}, {"id": "disc", "zh": "判别模型", "de": "Diskriminative Modelle", "one": "直接建模条件概率, 可以加入任意特征.", "a0": 2.8436, "a1": 3.678}, {"id": "eval", "zh": "评估方法", "de": "Evaluierung", "one": "用没见过的数据和金标准判断模型好坏, 差别是否显著.", "a0": 3.778, "a1": 4.2548}], "nodes": [{"id": "tokentype", "b": "korp", "zh": "词次与词型", "de": "Token & Type", "one": "Token 数每一次出现, Type 数不同的词.", "pts": ["《汤姆·索亚》: 71370 Token, 8018 Type", "只出现一次的叫 Hapax Legomena"], "ex": "der Hund und der Mann → 5 Token, 4 Type", "ang": -1.7825, "lv": 0, "rr": 0.167, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "dd": "Token sind die einzelnen Vorkommen von Wörtern im Text, Types die verschiedenen Wortformen.", "xp": "统计语料的第一步就是分清两种「数法」: Token 是逐次出现, Type 是不同的词形. 两者之比 (Type-Token-Verhältnis) 随语料变大而下降, 因为新词越来越少. 只出现一次的 Type 叫孤例词 (Hapax Legomena), 它们往往占全部 Type 的一半左右, 这正是后面数据稀疏的根源.", "sub": [{"id": "tokentype.ttr", "zh": "词型词次比", "de": "Type-Token-Verhältnis", "one": "Type 数除以 Token 数, 语料越大越小."}, {"id": "tokentype.hapax", "zh": "孤例词", "de": "Hapax Legomena", "one": "只出现一次的词, 约占 Type 的一半."}, {"id": "tokentype.freq2", "zh": "二阶频率", "de": "Häufigkeiten zweiter Ordnung", "one": "统计「出现 r 次的词有多少个」, 记作 N_r."}], "tm": [1, 2, 3, 65, 67], "q": "Zahl der unterschiedlichen Wörter: 8018 (Types)", "fol": "S. 9"}, {"id": "zipf", "b": "korp", "zh": "齐普夫定律", "de": "Zipf’sches Gesetz", "one": "词频与频率排名成反比, 所以大多数词都很罕见.", "pts": ["少数词极高频 (多为功能词)", "双对数坐标下近似斜率 −1 的直线", "直接造成数据稀疏"], "ex": "f · r ≈ K", "ang": -1.6452, "lv": 1, "rr": 0.5, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "dd": "Die Häufigkeit eines Wortes ist umgekehrt proportional zu seinem Rang in der Häufigkeitsliste.", "xp": "把词按频率从高到低排, 第 r 名的频率 f 大致满足 f · r ≈ K. 画在双对数坐标 (doppelt logarithmisch) 上近似一条斜率 −1 的直线. 含义是: 少数功能词极高频, 绝大多数词极罕见. 这决定了后面所有估计问题: 再大的语料, 也总有大量事件只见过一两次或没见过.", "sub": [{"id": "zipf.ranklist", "zh": "频率排序表", "de": "", "one": "词按频率降序排列, 名次即 Rang."}, {"id": "zipf.loglog", "zh": "双对数图", "de": "Doppelt logarithmische Darstellung", "one": "齐普夫分布在这种图上接近直线."}, {"id": "zipf.longtail", "zh": "罕见词", "de": "Seltene Wörter", "one": "大量低频词合起来仍占可观的概率质量."}], "tm": [4, 66]}, {"id": "null", "b": "korp", "zh": "零假设与显著性", "de": "Nullhypothese & Signifikanz", "one": "先假设要推翻的命题, 再看样本在该假设下是否极不可能.", "pts": ["p 值 = 拒绝零假设时犯错的概率", "小于约定阈值才算显著"], "ex": "30 次掷币里正面太多 → 硬币可能做过手脚", "ang": -1.4964, "lv": 0, "rr": 0.167, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "dd": "Die Nullhypothese ist die Annahme, die ein Test zu widerlegen versucht; signifikant ist ein Ergebnis, wenn es unter ihr sehr unwahrscheinlich ist.", "xp": "统计检验是反证思路: 先假设「没有效应」(零假设, Nullhypothese), 再算出在这个假设下得到当前或更极端结果的概率 (p 值). p 值小于事先约定的显著性水平 (Signifikanzniveau, 常为 0.05) 才拒绝零假设. 注意: 不显著不等于证明了零假设为真, 只是证据不够.", "sub": [{"id": "null.pval", "zh": "p 值", "de": "p-Wert", "one": "零假设成立时出现这么极端结果的概率."}, {"id": "null.alpha", "zh": "显著性水平", "de": "Signifikanzniveau", "one": "事先定的阈值, 常用 0.05 或 0.01."}, {"id": "null.coin", "zh": "做过手脚的硬币", "de": "Gezinkte Münze", "one": "30 次里正面太多, 就怀疑硬币被做了手脚."}], "tm": [5, 9, 68, 69, 70], "q": "Nullhypothese: Die Wahrscheinlichkeit von “Kopf” ist 0.5.", "fol": "S. 52"}, {"id": "binom", "b": "korp", "zh": "二项检验", "de": "Binomialtest", "one": "用二项分布算「至少出现这么多次」的概率, 再判断是否显著.", "pts": ["每个位置看成一次伯努利试验", "词对检验里 p 由两个词的独立频率给出"], "ex": "b(r; n, p)", "ang": -1.3591, "lv": 1, "rr": 0.5, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "dd": "Der Binomialtest berechnet, wie wahrscheinlich mindestens k Erfolge in n Versuchen unter der Nullhypothese sind.", "xp": "把每次观察看成一次伯努利试验 (Bernoulli-Experiment), 零假设给出成功概率 p. 二项检验把二项分布从 k 加到 n, 得到「至少这么多次」的尾部概率, 再和显著性水平比较. 用在搭配抽取时, p 由两个词各自的频率在独立假设下算出.", "sub": [{"id": "binom.tail", "zh": "上尾概率", "de": "Überschreitungswahrscheinlichkeit", "one": "Σ_{r≥k} b(r; n, p), 即单侧 p 值."}, {"id": "binom.bernoulli", "zh": "伯努利试验", "de": "Bernoulli-Experiment", "one": "只有成功和失败两种结果的单次试验."}], "tm": [6, 82], "q": "Beim Binomialtest gibt der berechnete Wert direkt die Wahrscheinlichkeit (= p-Wert) dafür an, einen Fehler zu machen, wenn wir die Nullhypothese zurückweisen.", "fol": "S. 67"}, {"id": "kolloc", "b": "korp", "zh": "搭配抽取", "de": "Kollokationsextraktion", "one": "找出比统计独立时预期更常一起出现的词对.", "pts": ["只按频率排, 前面全是功能词组合", "零假设: 两个词相互独立", "度量: 二项检验、χ²、t 分数、LLR、点互信息"], "ex": "new companies 并不显著", "ang": -1.4964, "lv": 2, "rr": 0.833, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "dd": "Kollokationsextraktion sucht Wortpaare, die häufiger gemeinsam auftreten, als bei statistischer Unabhängigkeit zu erwarten wäre.", "xp": "只按共现频率排, 排在前面的全是 der Hund 这类功能词组合, 没有意义. 所以要把观察到的共现次数和「两个词互相独立时」的期望次数比较, 差得越显著, 越像固定搭配 (Kollokation). 不同度量 (二项检验、χ²、t 分数、对数似然比、点互信息) 对低频词对的偏好不同, 结果排序也不同.", "sub": [{"id": "kolloc.pairs", "zh": "高频词对", "de": "Häufige Wortpaare", "one": "只看频率会被功能词组合占满."}, {"id": "kolloc.tscore", "zh": "t 分数", "de": "t-Score", "one": "用均值差除以标准差估计显著性, 偏爱高频词对."}, {"id": "kolloc.llr", "zh": "对数似然比", "de": "Log-Likelihood-Ratio", "one": "对低频词对也较稳, 常用的关联度量."}, {"id": "kolloc.pmi", "zh": "点互信息", "de": "Pointwise Mutual Information", "one": "log p(x,y)/(p(x)p(y)), 高估罕见词对."}], "tm": [7, 71, 73, 74, 75], "q": "Kollokationen sind feste Wortkombinationen, die beim Erwerb einer Sprache gelernt werden müssen.", "fol": "S. 57–58"}, {"id": "chi", "b": "korp", "zh": "卡方检验", "de": "χ²-Test", "one": "比较列联表的观察值和独立假设下的期望值.", "pts": ["χ² 越大, p 值越小", "要查表才能换算成 p 值"], "ex": "χ² = Σ (O − E)² / E", "ang": -1.7825, "lv": 1, "rr": 0.833, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "dd": "Der χ²-Test vergleicht beobachtete und unter Unabhängigkeit erwartete Häufigkeiten einer Kontingenztabelle.", "xp": "把两个词是否出现列成 2×2 列联表 (Kontingenztabelle), 每格算期望值 E = 行和 × 列和 / 总数, 再对 (O − E)² / E 求和. χ² 越大, 越不像独立. χ² 本身不是概率, 要查 χ² 分布表 (自由度 1) 换算成 p 值; 期望值太小时近似不可靠.", "sub": [{"id": "chi.ctab", "zh": "列联表", "de": "Kontingenztabelle", "one": "2×2 格: 两个词各自出现与否的组合频率."}, {"id": "chi.expect", "zh": "期望频率", "de": "Erwartete Häufigkeit", "one": "独立假设下每格应有的次数."}], "tm": [8, 43, 72]}, {"id": "cond", "b": "prob", "zh": "条件概率", "de": "Bedingte Wahrscheinlichkeit", "one": "已知 B 发生时 A 的概率.", "pts": ["所有序列模型都由条件概率相乘", "用相对频率估计: 联合频率 / 条件频率"], "ex": "p(A|B) = p(A∩B) / p(B)", "ang": -0.9921, "lv": 0, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "dd": "Die bedingte Wahrscheinlichkeit p(A|B) ist die Wahrscheinlichkeit von A, wenn bekannt ist, dass B eingetreten ist.", "xp": "条件概率是把样本空间缩小到 B 之后再看 A: p(A|B) = p(A∩B) / p(B). 课程里几乎所有模型都是条件概率的乘积. 估计时用相对频率: 联合频率除以条件的频率. 山羊问题 (Ziegenproblem) 是检验直觉的经典例子: 换门后赢的概率是 2/3.", "sub": [{"id": "cond.sample", "zh": "样本空间与事件", "de": "Ergebnisraum & Ereignis", "one": "随机试验所有结果的集合及其子集."}, {"id": "cond.goat", "zh": "山羊问题", "de": "Ziegenproblem", "one": "主持人开门提供了信息, 换门赢的概率是 2/3."}, {"id": "cond.joint", "zh": "联合分布", "de": "Gemeinsame Verteilung", "one": "多个随机变量同时取值的概率."}, {"id": "cond.marg", "zh": "边缘分布", "de": "Randverteilung", "one": "对其他变量求和得到单个变量的分布."}], "tm": [10, 11, 12, 13, 14, 18, 76, 77], "q": "Zufallsexperiment: Experiment (Versuch) mit mehreren möglichen Ausgängen (z.B. Wurf von zwei Würfeln)", "fol": "S. 15–16"}, {"id": "chain", "b": "prob", "zh": "链式法则", "de": "Kettenregel", "one": "把联合概率拆成一串条件概率的乘积.", "pts": ["对变量数量没有限制, 本身不做近似", "马尔可夫假设是在它之后才加的简化"], "ex": "p(a,b,c) = p(a) p(b|a) p(c|a,b)", "ang": -0.7098, "lv": 1, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "dd": "Die Kettenregel zerlegt eine gemeinsame Wahrscheinlichkeit exakt in ein Produkt bedingter Wahrscheinlichkeiten.", "xp": "p(a, b, c) = p(a) · p(b|a) · p(c|a, b). 这一步本身没有任何近似, 只是把定义反复展开. 问题在后面: 条件越来越长, 根本估计不出来. 所以马尔可夫模型、HMM、PCFG 都是在链式法则之后加独立性假设, 把条件截短.", "sub": [{"id": "chain.exact", "zh": "精确分解", "de": "", "one": "不做近似, 对变量个数没有限制."}, {"id": "chain.trunc", "zh": "缩短条件", "de": "", "one": "马尔可夫假设只保留最近 k 个符号."}], "tm": [19], "q": "Problem: Die Kettenregel ist eigentlich nur anwendbar, wenn alle Texte dieselbe Länge n besitzen.", "fol": "S. 76"}, {"id": "bayes", "b": "prob", "zh": "贝叶斯定理", "de": "Theorem von Bayes", "one": "把条件概率倒过来, 由先验和似然得到后验.", "pts": ["消歧时分母 p(y) 与候选无关, 可以去掉", "罕见病检测例: 阳性也不代表大概率患病"], "ex": "p(x|y) = p(y|x) p(x) / p(y)", "ang": -0.5191, "lv": 1, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "dd": "Das Theorem von Bayes kehrt eine bedingte Wahrscheinlichkeit um: p(x|y) = p(y|x) p(x) / p(y).", "xp": "我们想要的往往是「看到数据后哪个解释最可能」(后验, a-posteriori), 但能估计的是「每个解释产生这些数据的概率」(似然). 贝叶斯定理把两者连起来, 先验 p(x) 是解释本身的常见程度. 做消歧时分母 p(y) 对所有候选都一样, 求 argmax 时可以去掉. 罕见病检测例说明: 先验很小时, 阳性结果也可能多半是误报.", "sub": [{"id": "bayes.prior", "zh": "先验与后验", "de": "A-priori & A-posteriori", "one": "看数据之前和之后对假设的概率."}, {"id": "bayes.argmax", "zh": "省略分母", "de": "", "one": "p(y) 与候选无关, 比较时可省略."}, {"id": "bayes.disease", "zh": "罕见病检测", "de": "", "one": "先验很小时阳性也未必患病."}], "tm": [79, 80, 81], "q": "Man nennt p(x) auch Apriori- und p(x|y) Aposteriori-Wahrscheinlichkeit.", "fol": "S. 29"}, {"id": "indep", "b": "prob", "zh": "统计独立", "de": "Statistische Unabhängigkeit", "one": "联合概率等于两个边缘概率之积.", "pts": ["搭配检验的零假设", "朴素贝叶斯和 HMM 都靠独立假设化简"], "ex": "p(x,y) = p(x) p(y)", "ang": -0.8014, "lv": 0, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "dd": "Zwei Ereignisse sind statistisch unabhängig, wenn ihre gemeinsame Wahrscheinlichkeit gleich dem Produkt der Einzelwahrscheinlichkeiten ist.", "xp": "独立意味着知道一个变量不改变对另一个的判断: p(x|y) = p(x). 课程里它有两种用法: 一是作为要推翻的零假设 (搭配检验); 二是作为化简模型的假设 (朴素贝叶斯、HMM、PCFG). 第二种用法是有意的近似, 模型的很多弱点都来自它.", "sub": [{"id": "indep.asnull", "zh": "作为零假设", "de": "", "one": "搭配检验假设两个词互不相关."}, {"id": "indep.asmodel", "zh": "作为模型假设", "de": "", "one": "用独立性减少参数, 代价是忽略依赖."}], "tm": [78]}, {"id": "mlest", "b": "prob", "zh": "相对频率与最大似然", "de": "Relative Häufigkeit & MLE", "one": "用训练数据里的相对频率估计概率, 这就是最大似然估计.", "pts": ["让训练数据概率最大", "没见过的事件得到概率 0, 所以需要平滑"], "ex": "p̃(y|x) = f(x,y) / f(x)", "ang": -0.6107, "lv": 0, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "dd": "Die Maximum-Likelihood-Schätzung wählt die Parameter, die die Trainingsdaten am wahrscheinlichsten machen; für diskrete Verteilungen sind das relative Häufigkeiten.", "xp": "对离散分布, 让训练数据概率最大的参数恰好就是相对频率 f(x,y)/f(x). 它简单、无偏于训练数据, 却有致命问题: 没见过的事件概率为 0, 一个零就会让整句概率变成 0. 这就是参数平滑 (Parameterglättung) 存在的原因.", "sub": [{"id": "mlest.relfreq", "zh": "相对频率", "de": "Relative Häufigkeit", "one": "事件频率除以总频率."}, {"id": "mlest.zero", "zh": "零概率问题", "de": "Nullwahrscheinlichkeiten", "one": "没见过的事件被估成 0."}], "tm": [21, 22], "q": "Dies ist die Maximum-Likelihood-Schätzung (MLE) bzgl. der Trainingsdaten. Keine andere Wahl der Parameter weist den Trainingsdaten eine höhere Wahrscheinlichkeit zu.", "fol": "S. 85–86"}, {"id": "binomd", "b": "prob", "zh": "二项分布", "de": "Binomialverteilung", "one": "n 次独立伯努利试验里恰好出现 r 次「1」的概率.", "pts": ["由伯努利试验重复得到", "二项检验的基础"], "ex": "b(r; n, p) = C(n,r) pʳ (1−p)ⁿ⁻ʳ", "ang": -0.9005, "lv": 0, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "dd": "Die Binomialverteilung gibt die Wahrscheinlichkeit an, in n unabhängigen Bernoulli-Versuchen genau r Erfolge zu erhalten.", "xp": "b(r; n, p) = C(n, r) pʳ (1 − p)ⁿ⁻ʳ: 组合数数出 r 次成功的排列方式, 后面是每种排列的概率. 期望值是 np, 方差是 np(1 − p). 二项检验和符号检验都靠它算概率.", "sub": [{"id": "binomd.ev", "zh": "期望与方差", "de": "Erwartungswert & Varianz", "one": "E = np, Var = np(1 − p)."}, {"id": "binomd.randvar", "zh": "随机变量", "de": "Zufallsvariable", "one": "把试验结果映射成数值的函数."}], "tm": [15, 16, 17, 20, 83], "q": "Zufallsvariable: Funktion, welche jedem Ergebnis eine reelle Zahl zuweist.", "fol": "S. 21"}, {"id": "entropy", "b": "info", "zh": "熵", "de": "Entropie", "one": "一个随机事件平均提供多少信息, 也是最优编码平均码长的下限.", "pts": ["越不可能的事件信息量越大", "均匀分布时熵最大", "骰子约 2.58 比特"], "ex": "H(X) = − Σ p(x) log₂ p(x)", "ang": -0.0687, "lv": 0, "rr": 0.167, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "dd": "Die Entropie misst die durchschnittliche Unsicherheit einer Zufallsvariable, also den mittleren Informationsgehalt eines Ereignisses.", "xp": "一个事件的信息量是 −log₂ p: 越不可能, 发生时带来的信息越多. 熵是信息量的期望. 它也是编码 (Kodierung) 的下限: 平均每个符号至少需要 H 比特. 均匀分布时熵最大, 确定事件熵为 0. 公平骰子的熵约 2.58 比特.", "sub": [{"id": "entropy.infoamt", "zh": "信息量", "de": "Informationsgehalt", "one": "事件概率的负对数 −log₂ p."}, {"id": "entropy.code", "zh": "最优编码", "de": "Optimale Kodierung", "one": "平均码长不能低于熵."}, {"id": "entropy.maxent", "zh": "最大熵", "de": "Maximale Entropie", "one": "均匀分布时不确定性最大."}], "tm": [23, 84, 86], "q": "Die Entropie misst, wieviel Information ein Zufallsereignis im Mittel liefert.", "fol": "S. 37"}, {"id": "condh", "b": "info", "zh": "联合熵与条件熵", "de": "Gemeinsame & bedingte Entropie", "one": "条件熵是已知 X 后 Y 还剩多少不确定性.", "pts": ["联合熵可以分解成熵加条件熵"], "ex": "H(X,Y) = H(X) + H(Y|X)", "ang": 0.1764, "lv": 1, "rr": 0.5, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "dd": "Die bedingte Entropie H(Y|X) ist die Unsicherheit über Y, die bleibt, wenn X bekannt ist.", "xp": "联合熵 H(X, Y) 是两个变量一起的不确定性, 可以拆成 H(X) + H(Y|X): 先确定 X, 再看 Y 还剩多少不确定. 条件熵永远不大于 H(Y), 知道更多信息不会让不确定性变大 (平均意义上).", "sub": [{"id": "condh.jent", "zh": "联合熵", "de": "Gemeinsame Entropie", "one": "两个变量合起来的熵."}, {"id": "condh.chainh", "zh": "熵的链式法则", "de": "Kettenregel der Entropie", "one": "H(X,Y) = H(X) + H(Y|X)."}], "tm": [24, 85], "q": "Eine gemeinsame Wahrscheinlichkeit kann in ein Produkt bedingter Wahrscheinlichkeiten zerlegt werden.", "fol": "S. 28"}, {"id": "mi", "b": "info", "zh": "互信息", "de": "Mutual Information", "one": "知道一个变量后, 另一个变量的不确定性减少了多少.", "pts": ["独立时为 0", "点互信息可用作词的关联度量"], "ex": "I(X;Y) = H(X) − H(X|Y)", "ang": 0.062, "lv": 2, "rr": 0.833, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "dd": "Die Mutual Information misst, wie stark sich die Unsicherheit über eine Variable verringert, wenn man die andere kennt.", "xp": "I(X; Y) = H(X) − H(X|Y) = H(Y) − H(Y|X), 是对称的. 也可以看成联合分布与「假设独立」分布之间的 KL 距离, 所以独立时为 0. 对单个词对取点互信息 (PMI) 就得到一种搭配度量, 但它会高估只出现一两次的罕见词对.", "sub": [{"id": "mi.sym", "zh": "对称性", "de": "Symmetrie", "one": "I(X;Y) = I(Y;X)."}, {"id": "mi.pmi2", "zh": "点互信息", "de": "Punktweise MI", "one": "单个事件对的 log 比值, 用作关联度量."}], "tm": [25], "q": "Die Mutual Information I(X; Y) ist die “Schnittmenge” der Informationgehalte der beiden Zufallsvariablen X unf Y.", "fol": "S. 44"}, {"id": "kl", "b": "info", "zh": "相对熵", "de": "Relative Entropie (KL)", "one": "度量分布 p 和 q 之间的差异.", "pts": ["非负、不对称, 所以不是真正的距离", "p = q 时为 0"], "ex": "D(p‖q) = Σ p(x) log (p(x)/q(x))", "ang": -0.062, "lv": 0, "rr": 0.5, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "dd": "Die relative Entropie (Kullback-Leibler-Abstand) misst, wie viele zusätzliche Bits man braucht, wenn man Daten aus p mit einem Code für q kodiert.", "xp": "D(p‖q) = Σ p(x) log (p(x)/q(x)). 它非负, p = q 时为 0, 但不对称 (D(p‖q) ≠ D(q‖p)), 也不满足三角不等式, 所以不是真正的距离. 直观上它是用错误分布 q 编码带来的额外码长.", "sub": [{"id": "kl.asym", "zh": "不对称", "de": "Nicht symmetrisch", "one": "交换 p 和 q 结果不同."}, {"id": "kl.extra", "zh": "额外比特", "de": "", "one": "用 q 的编码表示 p 的数据多付的代价."}], "tm": [26], "q": "Die relative Entropie gibt an, wieviele Bits im Mittel verschenkt werden, wenn Ereignisse mit einer Verteilung p mit einem Code kodiert werden, der optimal für die Verteilung q ist.", "fol": "S. 47"}, {"id": "xent", "b": "info", "zh": "交叉熵与困惑度", "de": "Crossentropie & Perplexität", "one": "用模型 q 编码来自 p 的数据的平均码长, 用来比较语言模型.", "pts": ["交叉熵 = p 的熵 + KL 距离", "困惑度 = 2 的交叉熵次方", "在测试数据上越小越好"], "ex": "H(p,q) = H(p) + D(p‖q)", "ang": -0.1764, "lv": 1, "rr": 0.833, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "dd": "Die Crossentropie ist die mittlere Kodierungslänge von Daten aus p mit einem Modell q; die Perplexität ist 2 hoch die Crossentropie.", "xp": "真实分布 p 不知道, 但可以用测试数据估计交叉熵: −(1/N) Σ log₂ q(wᵢ). 它等于 H(p) + D(p‖q), 所以模型越接近真实分布越小. 困惑度 (Perplexität) = 2^H, 可以理解为模型每一步「平均在多少个词之间犹豫」. 只能在没见过的测试数据上比较.", "sub": [{"id": "xent.ppl", "zh": "困惑度", "de": "Perplexität", "one": "2 的交叉熵次方, 越小越好."}, {"id": "xent.testset", "zh": "在测试数据上估计", "de": "", "one": "用训练数据估会严重偏低."}], "tm": [27, 28], "q": "Das Modell mit der geringsten Crossentropie/Perplexität ist das beste.", "fol": "S. 106"}, {"id": "markov", "b": "lm", "zh": "马尔可夫模型", "de": "Markowmodell", "one": "假设下一个符号只依赖前 k 个符号.", "pts": ["k 阶模型 = (k+1)-gram 模型", "开头加 k 个起始符, 末尾加结束符", "可用于语种识别"], "ex": "p(wᵢ ∣ wᵢ₋ₖ … wᵢ₋₁)", "ang": 0.5191, "lv": 2, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "dd": "Ein Markowmodell k-ter Ordnung nimmt an, dass jedes Symbol nur von den k vorhergehenden Symbolen abhängt.", "xp": "链式法则之后加马尔可夫假设 (Markow-Annahme), 每个条件只保留前 k 个符号, k 阶模型就是 (k+1)-gram 模型. 句首补 k 个起始符, 句末加结束符 (Endesymbol), 这样不同长度的序列概率之和才是 1. 语种识别 (Sprachidentifizierung): 给每种语言训练一个字符级模型, 选让文本概率最大的语言.", "sub": [{"id": "markov.endsym", "zh": "结束符号", "de": "Endesymbol", "one": "保证所有长度的序列概率总和为 1."}, {"id": "markov.ngram", "zh": "n 元组", "de": "n-Gramm", "one": "k 阶马尔可夫模型 = (k+1)-gram."}, {"id": "markov.langid", "zh": "语种识别", "de": "Sprachidentifizierung", "one": "每种语言一个模型, 取概率最大者."}, {"id": "markov.wordmm", "zh": "词序列模型", "de": "Markowmodelle über Wortfolgen", "one": "符号换成词, 数据稀疏更严重."}], "tm": [29, 30, 87, 88, 89], "q": "Sprachmodelle werden oft in der Sprachverarbeitung verwendet (Spracherkennung, maschinelle Übersetzung, Sprachidentifizierung).", "fol": "S. 71–73"}, {"id": "sparse", "b": "lm", "zh": "数据稀疏", "de": "Sparse-Data-Problem", "one": "阶数越高, 越多 n-gram 在训练数据里从未出现.", "pts": ["零概率会让整段文本概率变成 0", "阶数的选择是偏差和稀疏之间的权衡"], "ex": "", "ang": 0.7098, "lv": 3, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "dd": "Je höher die Ordnung eines Modells, desto mehr mögliche Ereignisse kommen in den Trainingsdaten nie vor.", "xp": "参数个数随阶数指数增长 (词表 V 的三元组有 V³ 个), 训练数据却是固定的, 所以大部分 n-gram 一次都没见过, 最大似然把它们估成 0. 选阶数就是在「上下文更准 (偏差小)」和「估计更稀疏 (方差大)」之间权衡.", "sub": [{"id": "sparse.params", "zh": "参数爆炸", "de": "", "one": "n-gram 数量随 n 指数增长."}, {"id": "sparse.tradeoff", "zh": "偏差与稀疏", "de": "", "one": "阶数高更准但更稀疏."}], "tm": [31, 90], "q": "Prinzip der Parameterglättung: Man nimmt den beobachteten n-Grammen etwas Wahrscheinlichkeit weg und verteilt sie an die nicht beobachteten n-Gramme.", "fol": "S. 87"}, {"id": "addk", "b": "lm", "zh": "加 λ 平滑", "de": "Add-λ Glättung", "one": "给每个频率都加一个常数, 等价于和均匀分布插值.", "pts": ["λ = 1 就是拉普拉斯平滑", "属于线性折扣", "数据呈齐普夫分布时效果差"], "ex": "(f(w) + λ) / (N + Bλ)", "ang": 0.9005, "lv": 3, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "dd": "Bei der Add-λ Glättung wird zu jeder Häufigkeit eine Konstante λ addiert, bevor relative Häufigkeiten berechnet werden.", "xp": "p = (f(w) + λ) / (N + Bλ), B 是可能事件的个数. λ = 1 是拉普拉斯平滑 (Laplace-Glättung). 它等价于和均匀分布做线性插值, 属于线性折扣: 每个见过的事件都按比例让出概率. 对齐普夫分布的数据效果差: 让出的概率太多, 而且平均分给了海量没见过的事件.", "sub": [{"id": "addk.laplace", "zh": "加一平滑", "de": "Laplace-Glättung", "one": "λ = 1 的特例."}, {"id": "addk.lindisc", "zh": "线性折扣", "de": "Linear Discounting", "one": "按比例从所有事件扣概率."}], "tm": [91, 92], "q": "Linear Discounting (Add-λ Glättung) führt zu schlechten Ergebnissen, wenn die Daten eine Zipf’sche Verteilung aufweisen.", "fol": "S. 93"}, {"id": "absd", "b": "lm", "zh": "绝对折扣", "de": "Absolute Discounting", "one": "从每个见过的事件减去固定值 δ, 分给没见过的事件.", "pts": ["比线性折扣更符合齐普夫分布的数据", "δ 可由 N₁、N₂ 估计"], "ex": "δ = N₁ / (N₁ + 2N₂)", "ang": 0.6107, "lv": 3, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "dd": "Absolute Discounting zieht von jeder positiven Häufigkeit einen festen Betrag δ ab und verteilt die frei gewordene Masse auf ungesehene Ereignisse.", "xp": "平滑实验 (Glättungsexperiment) 拿两个同样大的语料比较: 训练里出现 r 次的二元组, 在新语料里平均出现的次数总比 r 少一个大致固定的量 (约 0.75–0.8), 例如 5 次的平均只剩 4.21 次; 加一平滑的预测则完全对不上. 所以从每个频率减固定的 δ, 比按比例扣更符合齐普夫分布. δ 可以用二阶频率估计: δ = N₁ / (N₁ + 2N₂).", "sub": [{"id": "absd.experiment", "zh": "平滑实验", "de": "Glättungsexperiment", "one": "见过 r 次的二元组在新语料里约少 0.75–0.8 次."}, {"id": "absd.adelta", "zh": "折扣值估计", "de": "", "one": "δ = N₁ / (N₁ + 2N₂)."}], "tm": [32]}, {"id": "backoff", "b": "lm", "zh": "回退平滑", "de": "Backoff-Glättung", "one": "n-gram 没见过时, 退到更短的上下文.", "pts": ["Katz: 只给没见过的事件回退", "插值: 回退概率加给所有事件, 通常略好"], "ex": "", "ang": 0.8014, "lv": 3, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "dd": "Backoff-Glättung greift auf ein Modell mit kürzerem Kontext zurück, wenn der längere Kontext zu selten beobachtet wurde.", "xp": "三元组没见过时, 用二元组甚至一元组的概率来补, 并乘一个回退因子 (Backoff-Faktor) 保证总和为 1. Katz 回退只给没见过的事件用回退分布; 插值回退 (interpoliert) 把回退概率加给所有事件, 通常略好. 回退分布本身也要平滑, 所以是递归的.", "sub": [{"id": "backoff.katz", "zh": "Katz 回退", "de": "Katz’sche Backoff-Glättung", "one": "只对未见事件回退到短上下文."}, {"id": "backoff.interp", "zh": "插值回退", "de": "Interpolierte Backoff-Glättung", "one": "所有事件都混入回退概率."}, {"id": "backoff.bofactor", "zh": "回退因子", "de": "Backoff-Faktor", "one": "把让出的概率质量按比例分给回退分布."}], "tm": [33, 34, 93, 95], "q": "Berechnung der Backoff-Faktoren (interpolierte Glättung)", "fol": "S. 105"}, {"id": "kn", "b": "lm", "zh": "Kneser-Ney 回退分布", "de": "Kneser-Ney-Backoff", "one": "一个词出现过的不同语境越多, 回退概率越大.", "pts": ["解决 Francisco 这类高频却只跟在 San 后面的词", "数类型, 不数词次"], "ex": "", "ang": 0.9921, "lv": 3, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "dd": "Die Kneser-Ney-Backoff-Verteilung schätzt die Wahrscheinlichkeit eines Wortes danach, in wie vielen verschiedenen Kontexten es vorkommt.", "xp": "问题例子: Francisco 词频很高, 但几乎只跟在 San 后面. 普通回退会在任何没见过的上下文里给它高概率, 这是错的. Kneser-Ney 的回退分布不数词次, 而数「它跟在多少种不同的词后面」(Type 而不是 Token), 只在回退时用这个分布.", "sub": [{"id": "kn.francisco", "zh": "San Francisco 问题", "de": "San-Francisco-Problem", "one": "高频但语境单一的词不该在回退时占优."}, {"id": "kn.contcount", "zh": "上下文种类数", "de": "", "one": "用前接词的种类数估计回退概率."}], "tm": [94], "q": "Die Kneser-Ney-Methode zählt n-Gramm-Types (statt -Tokens).", "fol": "S. 103"}, {"id": "nbwsd", "b": "tag", "zh": "朴素贝叶斯词义消歧", "de": "Naïve-Bayes-WSD", "one": "假设上下文词彼此独立, 选联合概率最大的词义.", "pts": ["输入是歧义词周围的实词", "需要标注了词义的语料", "可以用伪词造评估数据"], "ex": "ŝ = argmax p(s) Π p(cᵢ|s)", "ang": 1.3343, "lv": 2, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "nb", "dd": "Naïve-Bayes-Desambiguierung wählt die Bedeutung, die zusammen mit den Kontextwörtern am wahrscheinlichsten ist, unter der Annahme unabhängiger Kontextwörter.", "xp": "歧义词周围的实词当特征. 用贝叶斯定理 ŝ = argmax p(s) Π p(cᵢ|s), 「朴素」指假设各上下文词在给定词义下互相独立. 参数从标注了词义的语料用相对频率加平滑估计. 没有标注语料时可以造伪词 (Pseudowort): 把两个词合并, 再让模型把它们分开, 就有了现成的答案.", "sub": [{"id": "nbwsd.senses", "zh": "词义与翻译", "de": "Wortbedeutungen & Übersetzung", "one": "词义常以不同译文区分."}, {"id": "nbwsd.pseudo", "zh": "伪词评估", "de": "Pseudowort-Evaluierung", "one": "合并两个词制造人工歧义来评估."}, {"id": "nbwsd.nbparam", "zh": "参数估计", "de": "Parameterschätzung", "one": "p(s) 与 p(c|s) 用相对频率加平滑."}], "tm": [36, 37], "q": "Wir werden nun ein statistisches Modell für die Wortbedeutungs-Desambiguierung betrachten, welches als wesentliche Information die in der Nähe des mehrdeutigen Wortes aufgetretenen Inhaltswörter benutzt.", "fol": "S. 114"}, {"id": "hmm", "b": "tag", "zh": "隐马尔可夫模型", "de": "Hidden-Markow-Modell", "one": "词性序列是隐藏状态, 词由自己的词性发射出来.", "pts": ["假设: 词性只依赖前 k 个词性; 词只依赖自己的词性", "两类参数: 上下文概率、词汇概率", "典型准确率 95%–98%"], "ex": "p(t,w) = Π p(tᵢ|tᵢ₋₁) p(wᵢ|tᵢ)", "ang": 1.525, "lv": 3, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "dd": "Ein Hidden-Markow-Modell betrachtet die Wortartfolge als verborgene Zustandsfolge, aus der die Wörter emittiert werden.", "xp": "词性标注要选最可能的标签序列 t. 由贝叶斯得 argmax p(t) p(w|t), 再做两个假设: 标签只依赖前 k 个标签 (上下文概率 p(tᵢ|tᵢ₋₁)), 词只依赖自己的标签 (词汇概率 p(wᵢ|tᵢ)). 参数可以从标注语料直接数. 二元组标注器准确率约 95%–98%. 弱点: 右侧上下文 (rechter Satzkontext) 只能通过标签链间接影响.", "sub": [{"id": "hmm.ctxprob", "zh": "上下文概率", "de": "Kontextwahrscheinlichkeit", "one": "p(tᵢ | tᵢ₋₁), 标签之间的转移."}, {"id": "hmm.lexprob", "zh": "词汇概率", "de": "Lexikalische Wahrscheinlichkeit", "one": "p(wᵢ | tᵢ), 标签发射出词."}, {"id": "hmm.rightctx", "zh": "右侧上下文", "de": "Rechter Satzkontext", "one": "后面的词只能通过标签链影响当前决策."}, {"id": "hmm.posamb", "zh": "词性歧义", "de": "Wortart-Ambiguität", "one": "同一个词形可属于多个词类."}], "tm": [38, 39, 40, 97, 98], "q": "Dieses Modell heißt Hidden-Markow-Modell, weil die Zustände (Tags bzw. Tagpaare beim Trigramm-Tagger) nicht direkt beobachtbar sind.", "fol": "S. 129"}, {"id": "viterbi", "b": "tag", "zh": "Viterbi 算法", "de": "Viterbi-Algorithmus", "one": "用动态规划求最佳序列, 每个状态只保留最优前缀.", "pts": ["复杂度随句长线性增长", "代价: 花园路径句无法正确处理", "同一思路可用于 PCFG 和 CRF"], "ex": "δₜ(k) = max δₜ′(k−1) p(t|t′) p(wₖ|t)", "ang": 1.7157, "lv": 3, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "dd": "Der Viterbi-Algorithmus findet die wahrscheinlichste Zustandsfolge mit dynamischer Programmierung, indem er pro Zustand nur das beste Präfix behält.", "xp": "列举所有标签序列是指数级的. 关键观察: 到达某位置某标签的最佳路径, 一定由前一位置某标签的最佳路径延长而来 (可用反证法证明). 所以每个格子只存最佳概率 δ 和回指针, 时间复杂度对句长线性, 对标签数是 k+1 次方. 三元组标注器的状态是标签对.", "sub": [{"id": "viterbi.vdelta", "zh": "Viterbi 概率", "de": "Viterbi-Wahrscheinlichkeit", "one": "δₜ(k): 到位置 k 标签 t 的最佳前缀概率."}, {"id": "viterbi.backptr", "zh": "回溯指针", "de": "", "one": "记录最佳前驱, 最后倒推出序列."}, {"id": "viterbi.proof", "zh": "反证法", "de": "Widerspruchsbeweis", "one": "证明最佳路径的前缀也必然最佳."}, {"id": "viterbi.complexity", "zh": "时间复杂度", "de": "Rechenzeit-Komplexität", "one": "句长线性, 标签数的 k+1 次方."}], "tm": [41, 99], "q": "Wir berechnen für jede Regel und jedes Nichtterminal der Parsewald-Grammatik eine Viterbi-Wahrscheinlichkeit.", "fol": "S. 207"}, {"id": "unk", "b": "tag", "zh": "未知词处理", "de": "Unbekannte Wörter", "one": "用大小写和词尾推断没见过的词的词性.", "pts": ["把 p(w|t) 换成 p(t|w)/p(t)", "后缀长度逐级回退"], "ex": "", "ang": 1.4258, "lv": 3, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "dd": "Für unbekannte Wörter schätzt der Tagger die Wortart aus Merkmalen wie Großschreibung und Wortendung.", "xp": "测试数据里总有训练没见过的词, p(w|t) 无法直接估计. 办法是借贝叶斯把 p(w|t) 换成 p(t|w)/p(t) (常数项可略), 再用词尾估 p(t|后缀): 后缀从长到短逐级回退, 长后缀更准但更稀疏. 大小写是另一个强特征.", "sub": [{"id": "unk.suffix", "zh": "后缀回退", "de": "Suffix-Backoff", "one": "从最长后缀逐级退到短后缀."}, {"id": "unk.caps", "zh": "大小写", "de": "Großschreibung", "one": "德语名词和专名的重要线索."}], "tm": [96, 106], "q": "Neben unbekannten Wörtern stellen auch ungesehene Tags bekannter Wörter ein Problem dar (bspw. wenn das englische Wort “indicate” nur als Infinitiv aber nicht als finites Verb aufgetaucht ist.)", "fol": "S. 137"}, {"id": "fb", "b": "tag", "zh": "Forward-Backward 算法", "de": "Forward-Backward-Algorithmus", "one": "用动态规划算期望的标签频率, 不用列举所有序列.", "pts": ["前向概率 × 后向概率", "EM 的 E 步要用它"], "ex": "", "ang": 1.6166, "lv": 3, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "dd": "Der Forward-Backward-Algorithmus berechnet die erwarteten Tag-Häufigkeiten über alle Tagfolgen mit dynamischer Programmierung.", "xp": "前向概率 α 是「从句首到这里、停在这个标签」的所有路径概率之和, 后向概率 β 是「从这里到句尾」的总和. α · β / p(w) 就是该位置取该标签的概率, 把它当作「期望频率」, 不用列举所有序列. 公式结构和 Viterbi 一样, 只是把 max 换成求和.", "sub": [{"id": "fb.alpha", "zh": "前向概率", "de": "Forward-Wahrscheinlichkeit", "one": "到当前位置和标签的所有前缀概率之和."}, {"id": "fb.beta", "zh": "后向概率", "de": "Backward-Wahrscheinlichkeit", "one": "从当前位置到句尾的所有后缀概率之和."}], "tm": [42, 100, 101], "q": "Berechnung der erwarteten Wort-Tag- und Tag-Tag-Häufigkeiten mit dem Forward-Backward-Algorithmus (E-Schritt)", "fol": "S. 168"}, {"id": "em", "b": "tag", "zh": "EM 训练", "de": "EM-Training", "one": "在无标注数据上交替估计期望频率和重新估计参数.", "pts": ["数据似然单调上升, 只收敛到局部最大", "有监督训练通常更好"], "ex": "", "ang": 1.8073, "lv": 3, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "dd": "Das EM-Verfahren schätzt Parameter auf unannotierten Daten, indem es abwechselnd erwartete Häufigkeiten berechnet (E-Schritt) und daraus neue Parameter schätzt (M-Schritt).", "xp": "没有标注语料时, 先随便给一组参数, E 步用当前参数算每种分析的权重 (期望频率), M 步把这些期望频率当真实频率做相对频率估计. 每轮数据似然都不会下降, 但只收敛到局部最大, 结果依赖初值. 实践中有监督训练通常更好, EM 常用来在少量标注之外补充.", "sub": [{"id": "em.estep", "zh": "E 步", "de": "E-Schritt", "one": "用当前参数算期望频率."}, {"id": "em.mstep", "zh": "M 步", "de": "M-Schritt", "one": "用期望频率重新做相对频率估计."}, {"id": "em.local", "zh": "局部最大值", "de": "Lokales Maximum", "one": "似然单调上升, 但不保证全局最优."}], "tm": [102, 103, 104, 105], "q": "EM passt die Parameter an die Trainingsdaten an.", "fol": "S. 220"}, {"id": "pcfg", "b": "parse", "zh": "概率上下文无关文法", "de": "Probabilistische kontextfreie Grammatik", "one": "给每条文法规则一个概率, 树的概率是所用规则概率之积.", "pts": ["左部相同的规则概率之和为 1", "句子概率 = 所有分析树概率之和"], "ex": "p(T) = Π p(rᵢ)", "ang": 2.1743, "lv": 0, "rr": 0.167, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "dd": "Eine probabilistische kontextfreie Grammatik ordnet jeder Regel eine Wahrscheinlichkeit zu; die Wahrscheinlichkeit eines Parsebaums ist das Produkt seiner Regelwahrscheinlichkeiten.", "xp": "句法歧义使一个句子有多棵分析树, 要选最可能的. PCFG 给每条规则 A → α 一个条件概率 p(α|A), 左部相同的规则概率之和为 1. 树概率是所用规则概率之积, 句子概率是所有分析树概率之和. 这背后是很强的独立性假设: 规则展开只看左部范畴, 不看位置和上下文.", "sub": [{"id": "pcfg.cfg", "zh": "上下文无关文法", "de": "Kontextfreie Grammatik", "one": "规则左部只有一个非终结符."}, {"id": "pcfg.deriv", "zh": "推导", "de": "Ableitung", "one": "从起始符逐步改写到句子, 对应一棵树."}, {"id": "pcfg.synamb", "zh": "句法歧义", "de": "Syntaktische Ambiguität", "one": "同一句子有多种合法结构."}], "tm": [46, 107, 108, 109, 110, 111], "q": "Zu jeder (partiellen) Linksableitung gibt es einen eindeutigen (partiellen) Parsebaum und umgekehrt.", "fol": "S. 183"}, {"id": "treebank", "b": "parse", "zh": "树库训练", "de": "Baumbank-Training", "one": "从人工标注的树库里数规则频率, 用相对频率估计规则概率.", "pts": ["建树库费力又昂贵", "树库训练明显好于 EM 训练"], "ex": "", "ang": 2.4604, "lv": 1, "rr": 0.167, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "dd": "Beim Baumbank-Training werden Regelwahrscheinlichkeiten als relative Häufigkeiten der Regeln in einer manuell annotierten Baumbank geschätzt.", "xp": "树库 (Baumbank) 是人工标好句法树的语料. 从中读出所有规则, 用 f(A → α) / f(A) 估计规则概率, 就是 PCFG 的最大似然估计. 建树库费时昂贵, 但树库训练明显好于只用无标注数据的 EM 训练. 简单树库文法的弱点在于范畴太粗.", "sub": [{"id": "treebank.readrules", "zh": "抽取规则", "de": "", "one": "树里每个局部子树就是一条规则."}, {"id": "treebank.unannot", "zh": "无标注训练", "de": "Training auf unannotierten Daten", "one": "用 Inside-Outside 做 EM, 效果较差."}], "tm": [45, 112], "q": "Baumbanken müssen manuell erstellt werden.", "fol": "S. 189"}, {"id": "forest", "b": "parse", "zh": "分析森林", "de": "Parsewald", "one": "合并共同子树, 紧凑地表示一个句子的所有分析.", "pts": ["分析树数量可随句长指数增长", "森林上可以跑 Viterbi 和 Inside-Outside"], "ex": "", "ang": 2.5977, "lv": 3, "rr": 0.5, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "dd": "Ein Parsewald repräsentiert alle Analysen eines Satzes kompakt, indem gemeinsame Teilbäume nur einmal gespeichert werden.", "xp": "分析树的数量可能随句长指数增长, 但它们共享大量子树. 分析森林把相同跨度、相同范畴的子树合并成一个节点, 本身可以看成一部只生成这个句子的专用文法 (spezialisierte Grammatik). 在森林上可以高效地做 Viterbi (找最佳树) 和 Inside-Outside (算期望频率).", "sub": [{"id": "forest.special", "zh": "专用文法", "de": "Spezialisierte Grammatik", "one": "森林 = 只生成当前句子的文法."}, {"id": "forest.pviterbi", "zh": "森林上的 Viterbi", "de": "Viterbi auf Parsewäldern", "one": "每个节点保留最佳子树概率."}], "tm": [44], "q": "(derselbe Parsewald wie auf S. 205)", "fol": "S. 206"}, {"id": "io", "b": "parse", "zh": "Inside-Outside 算法", "de": "Inside-Outside-Algorithmus", "one": "高效计算 EM 所需的期望规则频率, 相当于 PCFG 版的 Forward-Backward.", "pts": ["Inside = 节点所有内部推导的总概率", "Outside = 节点之外部分的总概率", "公式和 Viterbi 只差 max 换成求和"], "ex": "γ(A) = α(A) β(A) / α(S)", "ang": 2.1743, "lv": 3, "rr": 0.833, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "dd": "Der Inside-Outside-Algorithmus berechnet für jeden Knoten des Parsewalds die Inside- und Outside-Wahrscheinlichkeit und daraus erwartete Regelhäufigkeiten.", "xp": "Inside 概率 β(A) 是节点 A 下面所有子树的总概率 (自下而上算), Outside 概率 α(A) 是节点外面其余部分的总概率 (自上而下算). 某条规则在这个句子里的期望次数 = α · 规则概率 · 子节点 β 的乘积 / 句子概率. 这些期望频率进入 EM 的 M 步, 重新估计规则概率. 它是 PCFG 版的 Forward-Backward.", "sub": [{"id": "io.inside", "zh": "Inside 概率", "de": "Inside-Wahrscheinlichkeit", "one": "节点内部所有推导的概率之和."}, {"id": "io.outside", "zh": "Outside 概率", "de": "Outside-Wahrscheinlichkeit", "one": "节点之外部分的概率之和."}, {"id": "io.reest", "zh": "规则重估", "de": "Neuschätzung der Regelwahrscheinlichkeiten", "one": "期望规则频率归一化成新概率."}], "tm": [113, 114, 115], "q": "Die Inside-Wahrscheinlichkeiten α(.) wurden schon berechnet. Die Regelwahrscheinlichkeiten p(S → NP VP) etc. sind gegeben. Die Outside-Wahrscheinlichkeiten β(.) werden top-down berechnet.", "fol": "S. 214"}, {"id": "refine", "b": "parse", "zh": "文法细化", "de": "Baumbank-Annotation", "one": "给范畴加上下文信息, 削弱 PCFG 过强的独立性假设.", "pts": ["父节点标注可区分主语和宾语 NP", "马尔可夫化处理扁平树库的长规则"], "ex": "", "ang": 2.3116, "lv": 1, "rr": 0.5, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "berkeley", "dd": "Bei der Baumbank-Annotation werden Kategorien mit Kontextinformation angereichert, um die zu starken Unabhängigkeitsannahmen der PCFG abzuschwächen.", "xp": "简单树库文法里, 主语 NP 和宾语 NP 是同一个范畴, 展开概率被平均掉了. 解决办法是把信息写进范畴名: 父节点标注 (Elternannotation, NP^S 与 NP^VP)、形态句法信息、论元信息等. 范畴变细后规则变多, 又会稀疏. 扁平树库的长规则用马尔可夫化 (Markowisierung) 拆成短的生成步骤.", "sub": [{"id": "refine.parent", "zh": "父节点标注", "de": "Elternannotation", "one": "给范畴加上父节点, 区分主语和宾语 NP."}, {"id": "refine.morphann", "zh": "形态句法标注", "de": "Morphosyntaktische Annotation", "one": "把格、数等信息并入范畴."}, {"id": "refine.markovize", "zh": "马尔可夫化", "de": "Markowisierung", "one": "把长规则分解成逐个生成子节点."}, {"id": "refine.trace", "zh": "移位痕迹标注", "de": "Spurmerkmal", "one": "痕迹到填充词路径上的节点都带移位标记."}], "tm": [47, 48], "q": "Die gezeigte Markowisierung ist äquivalent dazu, dass wir die rechten Seiten (und Wahrscheinlichkeiten) von bspw. NP-Regeln mit einem Markow-Modell 2. Ordnung erzeugen.", "fol": "S. 247"}, {"id": "berkeley", "b": "parse", "zh": "Berkeley 分析器", "de": "Berkeley-Parser", "one": "自动学习子范畴: 反复分裂范畴, 用 EM 训练, 再合并没用的分裂.", "pts": ["省去手工设计特征", "每轮: Split → EM → Merge"], "ex": "", "ang": 2.4604, "lv": 3, "rr": 0.833, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "berkeley", "dd": "Der Berkeley-Parser lernt verfeinerte Kategorien automatisch, indem er Kategorien wiederholt aufspaltet, mit EM trainiert und unnütze Aufspaltungen wieder vereinigt.", "xp": "手工设计细化特征很费力. Berkeley 分析器把每个范畴自动一分为二 (如 NP-1, NP-2), 用 EM 训练子范畴的规则概率, 再把对似然贡献小的分裂合并回去 (Vereinigung), 如此递归多轮. 得到的子范畴往往对应语言学上可解释的区别.", "sub": [{"id": "berkeley.split", "zh": "分裂", "de": "Aufspaltung", "one": "每个范畴一分为二, 加一点随机扰动."}, {"id": "berkeley.merge", "zh": "合并", "de": "Vereinigung", "one": "撤销收益小的分裂, 控制文法规模."}, {"id": "berkeley.recur", "zh": "递归细化", "de": "Rekursive Verfeinerung", "one": "Split → EM → Merge 重复多轮."}], "tm": [116]}, {"id": "generative", "b": "disc", "zh": "生成与判别", "de": "Generativ vs. diskriminativ", "one": "生成模型定义联合概率, 判别模型直接定义条件概率 p(c|d).", "pts": ["生成模型很难加入新信息", "判别模型可以加任意特征"], "ex": "", "ang": 3.1647, "lv": 0, "rr": 0.125, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "dd": "Generative Modelle definieren eine gemeinsame Wahrscheinlichkeit p(d, c); diskriminative Modelle definieren direkt die bedingte Wahrscheinlichkeit p(c | d).", "xp": "生成模型 (朴素贝叶斯、HMM、PCFG) 描述数据怎样「生成」出来, 要为输入本身建模. 想加一条新信息 (比如「词以 -ung 结尾」), 就得改写整个生成过程并处理特征之间的依赖. 判别模型只管给定输入时输出的概率, 可以随意加入互相重叠的特征 (Merkmale), 这是它的主要优势.", "sub": [{"id": "generative.feat", "zh": "特征", "de": "Merkmal", "one": "描述输入的指示函数, 可任意定义."}, {"id": "generative.gendis", "zh": "生成模型的缺点", "de": "Nachteile generativer Modelle", "one": "很难加入相互依赖的新信息."}], "tm": [49, 50, 51, 117], "q": "Manuell erstellte Merkmalsfunktionen extrahieren relevante Information aus dem Dokumentz.B. das Vorkommen eines Wortes wie “Lotterie”.", "fol": "S. 261"}, {"id": "linclf", "b": "disc", "zh": "线性分类器", "de": "Lineare Klassifikatoren", "one": "特征值和权重相乘求和, 分数决定类别.", "pts": ["权重 > 0 指向正类, < 0 指向负类", "朴素贝叶斯也可写成线性形式"], "ex": "score = θ · f(x)", "ang": 3.174, "lv": 1, "rr": 0.375, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "dd": "Ein linearer Klassifikator berechnet für jede Klasse eine gewichtete Summe der Merkmalswerte und wählt die Klasse mit dem höchsten Score.", "xp": "每个特征有一个权重 (Gewicht), 分数 = 权重向量 · 特征向量. 正权重支持该类, 负权重反对. 多类问题 (Mehrklassen-Probleme) 时特征和类别成对定义, 取分数最高的类. 朴素贝叶斯取对数后也是线性形式, 只是权重被固定为对数概率.", "sub": [{"id": "linclf.fvec", "zh": "特征向量", "de": "Merkmalsvektor", "one": "每个维度一个特征的取值."}, {"id": "linclf.multi", "zh": "多类问题", "de": "Mehrklassen-Problem", "one": "每个类各算分数, 取最大."}, {"id": "linclf.nbcmp", "zh": "与朴素贝叶斯比较", "de": "Vergleich mit Naive Bayes", "one": "朴素贝叶斯是权重固定的线性分类器."}], "tm": [118, 119, 120], "q": "Die Gewichte aller Merkmale, deren Wert von 0 verschieden ist, fließen in die Klassifikation ein.", "fol": "S. 264"}, {"id": "perceptron", "b": "disc", "zh": "感知机算法", "de": "Perzeptron-Algorithmus", "one": "分错时提高正确答案分数、降低错误答案分数.", "pts": ["线性可分时一定收敛", "不可分时不收敛, 容易过拟合"], "ex": "θ ← θ + f(x,y) − f(x,z)", "ang": 3.5078, "lv": 2, "rr": 0.375, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "perz", "dd": "Der Perzeptron-Algorithmus passt die Gewichte nur bei Fehlklassifikationen an: Merkmale der richtigen Klasse werden verstärkt, die der falschen geschwächt.", "xp": "逐个看训练样本, 预测对了不动; 错了就把正确答案的特征向量加到权重上, 把错误答案的减掉. 数据线性可分时保证收敛. 数据不是线性可分时不会收敛, 一直训练又会过拟合, 所以停止条件 (Stoppkriterium) 是: 每遍历一遍训练数据 (Epoche) 就在留出数据上评估, 保留最好的那组权重. 缺点是不给概率.", "sub": [{"id": "perceptron.update", "zh": "更新规则", "de": "Update-Regel", "one": "w ← w + f(x, y) − f(x, ŷ)."}, {"id": "perceptron.stop", "zh": "停止条件", "de": "Stoppkriterium", "one": "每个 epoch 在留出数据上评估, 留最好的权重."}], "tm": [52], "q": "Diese Methode wendet der Perzeptron-Algorithmus an, den wir als Nächstes behandeln. Später werden wir sehen, wie man den Score in eine Wahrscheinlichkeit transformiert (⇒ log-lineare Modelle).", "fol": "S. 265"}, {"id": "loglin", "b": "disc", "zh": "对数线性模型", "de": "Log-lineares Modell", "one": "分数取指数再归一化, 得到条件概率.", "pts": ["别名: 最大熵模型; 二分类时叫逻辑回归", "最优时期望频率 = 观察频率"], "ex": "p(y|x) = exp(θ·f(x,y)) / Z", "ang": 3.0138, "lv": 2, "rr": 0.625, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "dd": "Ein log-lineares Modell wandelt die linearen Scores mit der Exponentialfunktion und Normierung in Wahrscheinlichkeiten um.", "xp": "p(c|d) = exp(θ · f(d, c)) / Z(d), Z 把所有类的分数归一化. 也叫最大熵模型或多项逻辑回归. 训练目标是最大化训练数据的条件对数似然, 它对权重的偏导数有很漂亮的形式: 观察到的特征频率减去模型期望的特征频率. 两者相等时达到最优.", "sub": [{"id": "loglin.norm", "zh": "归一化", "de": "Normierung", "one": "Z(d) 对所有类求和, 让概率之和为 1."}, {"id": "loglin.alias", "zh": "别名", "de": "Maximum-Entropie-Modell", "one": "也叫最大熵模型、多项逻辑回归."}, {"id": "loglin.deriv", "zh": "偏导数", "de": "Partielle Ableitung", "one": "观察特征频率 − 期望特征频率."}], "tm": [53, 121, 123], "q": "Ein solches Modell heißt log-lineares Modell.", "fol": "S. 279"}, {"id": "grad", "b": "disc", "zh": "梯度上升", "de": "Gradientenanstieg", "one": "沿对数似然增大的方向更新参数.", "pts": ["梯度 = 观察频率 − 期望频率", "SGD 每个样本后更新, 学得快"], "ex": "θ ← θ + η ∇L", "ang": 3.3476, "lv": 3, "rr": 0.625, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "dd": "Beim Gradientenanstieg werden die Parameter schrittweise in Richtung des Gradienten der Zielfunktion verändert.", "xp": "梯度是各个偏导数组成的向量, 指向目标函数增长最快的方向. 每步把权重沿梯度走一小步 (学习率 η). 变体有批量 (Batch)、随机梯度 (SGD, 每个样本更新一次) 和小批量. 对数线性模型的对数似然是凹函数, 所以不会卡在局部最大.", "sub": [{"id": "grad.lr", "zh": "学习率", "de": "Lernrate", "one": "每步走多远, 太大会震荡."}, {"id": "grad.sgd", "zh": "随机梯度", "de": "Stochastischer Gradientenanstieg", "one": "每个样本就更新, 更快但更抖."}, {"id": "grad.other", "zh": "其他训练方法", "de": "Andere Lernalgorithmen", "one": "除梯度上升外还有 L-BFGS 等更快的优化方法."}], "tm": [54, 122, 124, 125], "q": "Der Gradient wird mit der Lernrate multipliziert und zum Gewichtsvektor addiert. (Gradientenanstieg)", "fol": "S. 305"}, {"id": "reg", "b": "disc", "zh": "正则化", "de": "Regularisierung", "one": "惩罚大权重, 防止过拟合.", "pts": ["L₂: 权重平方和", "L₁: 权重绝对值之和"], "ex": "", "ang": 3.174, "lv": 3, "rr": 0.875, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "dd": "Regularisierung bestraft große Gewichte in der Zielfunktion, um Überanpassung an die Trainingsdaten zu vermeiden.", "xp": "特征很多时, 模型会给只在训练数据里偶然有用的特征很大的权重, 这是过拟合 (Overfitting). 在目标函数里减去权重的平方和 (L2, 高斯先验) 或绝对值和 (L1, 会让很多权重变成 0), 正则项的偏导数也很简单, 直接加进梯度里.", "sub": [{"id": "reg.l2", "zh": "L2 正则", "de": "L2-Regularisierung", "one": "惩罚权重平方, 让权重整体变小."}, {"id": "reg.l1", "zh": "L1 正则", "de": "L1-Regularisierung", "one": "惩罚绝对值, 产生稀疏权重."}], "tm": [55, 56], "q": "µ bestimmt, wie stark regularisiert wird. Keine Regularisierung für µ = 0. µ kann auf Development-Daten optimiert werden und hat einen Wert ≥ 0 und (normalerweise) < 1.", "fol": "S. 291"}, {"id": "crf", "b": "disc", "zh": "条件随机场", "de": "Conditional Random Field", "one": "给定词序列时标签序列的条件概率, 特征可以看整个句子.", "pts": ["形式和 HMM 对应, 也用 Viterbi 解码", "训练时用 Forward-Backward 算期望频率", "主要工作是特征工程"], "ex": "", "ang": 3.5078, "lv": 3, "rr": 0.875, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "crf", "dd": "Ein Conditional Random Field ist ein log-lineares Modell über ganze Tagfolgen, dessen Merkmale benachbarte Tags und das Wort verbinden.", "xp": "线性链 CRF (Linear-Chain CRF) 把整个标签序列当作一个「类」, 分数是每个位置局部特征的和, 所以可以用 Viterbi 找最佳序列. 训练时梯度要用期望特征频率, 而期望要对指数多的序列求和, 这一步借用 Forward-Backward 算. 它结合了 HMM 的序列结构和判别模型的任意特征.", "sub": [{"id": "crf.lcrf", "zh": "线性链 CRF", "de": "Linear-Chain CRF", "one": "特征只连接相邻标签和当前位置的词."}, {"id": "crf.crfvit", "zh": "CRF 的 Viterbi", "de": "Viterbi für CRFs", "one": "局部分数相加, 动态规划求最佳序列."}, {"id": "crf.crftrain", "zh": "CRF 训练", "de": "Training von CRFs", "one": "SGD 加 Forward-Backward 算期望."}], "tm": [126], "q": "Das Training von CRFs ist iterativ.", "fol": "S. 305"}, {"id": "gold", "b": "eval", "zh": "金标准与测试数据", "de": "Goldstandard & Testdaten", "one": "把系统输出和人工标注比较, 测试数据不能参与训练.", "pts": ["在训练数据上评估会高估", "超参数要用开发数据选"], "ex": "", "ang": 3.8753, "lv": 0, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "dd": "Ein Modell wird auf Testdaten, die beim Training nicht verwendet wurden, mit einem manuell erstellten Goldstandard verglichen.", "xp": "金标准 (Goldstandard) 是人工给出的正确答案. 评估必须在训练没用过的测试数据上做, 否则只测到了记忆能力. 调整元参数 (Metaparameter, 如平滑参数) 要用单独的开发数据 (Entwicklungsdaten), 测试数据只在最后用一次.", "sub": [{"id": "gold.dev", "zh": "开发数据", "de": "Entwicklungsdaten", "one": "用来调元参数, 和测试数据分开."}, {"id": "gold.meta", "zh": "元参数", "de": "Metaparameter", "one": "不由训练直接估计的设置, 如 λ."}], "tm": [35, 57, 61, 62, 127, 128], "q": "In der Praxis ist k ein Hyperparameter, der auf Development-Daten optimiert werden kann.", "fol": "S. 79"}, {"id": "prf", "b": "eval", "zh": "精确率、召回率、F 值", "de": "Precision, Recall, F-Score", "one": "按成分计数, 分别看输出的正确率和金标准的覆盖率.", "pts": ["精确率 = TP/(TP+FP)", "召回率 = TP/(TP+FN)", "F 值是调和平均"], "ex": "F = 2PR / (P + R)", "ang": 3.9668, "lv": 1, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "dd": "Precision ist der Anteil korrekter unter den gefundenen Elementen, Recall der Anteil gefundener unter den korrekten; der F-Score ist ihr harmonisches Mittel.", "xp": "句法分析器评估时把每棵树拆成带标签的成分 (范畴 + 跨度), 和金标准树比较. 精确率 = 正确成分 / 系统给出的成分, 召回率 = 正确成分 / 金标准成分. F 值 = 2PR / (P + R). 只看一个指标会被钻空子: 少输出能提高精确率, 多输出能提高召回率.", "sub": [{"id": "prf.precision", "zh": "精确率", "de": "Precision", "one": "找出来的里面有多少是对的."}, {"id": "prf.recall", "zh": "召回率", "de": "Recall", "one": "该找的里面找到了多少."}, {"id": "prf.fscore", "zh": "F 值", "de": "F-Score", "one": "P 和 R 的调和平均."}], "tm": [63, 64, 129], "q": "Mit dem Recall messen wir zusätzlich, wieviel Prozent der Goldstandard-Konstituenten im Parse enthalten waren. Zusammen ergeben Precision und Recall ein genaues Bild der Parsing-Genauigkeit.", "fol": "S. 225"}, {"id": "sign", "b": "eval", "zh": "符号检验", "de": "Vorzeichentest", "one": "只看恰好一个系统出错的词, 判断两个系统的差别是否显著.", "pts": ["其余词一律忽略", "零假设下两个系统各胜一半"], "ex": "", "ang": 4.1575, "lv": 1, "rr": 0.75, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "dd": "Der Vorzeichentest prüft, ob ein System bei den Fällen, in denen sich zwei Systeme unterscheiden, signifikant häufiger richtig liegt.", "xp": "比较两个标注器时, 只看两者结果不同的句子或词: 记下 A 对 B 错和 B 对 A 错的次数. 零假设是两者一样好, 即每种情况概率 0.5, 于是用二项分布算出这种不平衡有多大可能是偶然的. 简单, 不需要假设分布形状.", "sub": [{"id": "sign.diffcases", "zh": "只计分歧样例", "de": "", "one": "两个系统都对或都错的情况不计."}], "tm": [60], "q": "Dazu wenden wir einen Signifikanztest an. Wir werden den Vorzeichentest nehmen.", "fol": "S. 150"}, {"id": "baseline", "b": "eval", "zh": "基线与上限", "de": "Baseline & Obergrenze", "one": "基线给最低标准, 上限给理论能达到的水平.", "pts": ["词义消歧基线: 总选最常见的读法", "上限: 人工标注者之间的一致率"], "ex": "", "ang": 4.066, "lv": 0, "rr": 0.25, "f": "SMIS-合集-语言处理中的统计方法.html", "a": "nb", "dd": "Die Baseline ist eine einfache Vergleichsmethode, die Obergrenze die Leistung, die ein perfektes oder menschliches System erreichen würde.", "xp": "只说「准确率 90%」没有意义, 要放在基线和上限之间看. 词义消歧的常用基线是总选最常见的词义 (most frequent sense), 上限可以用人在这个任务上的准确率. 例如一个词 80% 的时候是意义 A, 基线就已经有 80%. 模型只有明显超过基线才算有用.", "sub": [{"id": "baseline.mfs", "zh": "最高频词义", "de": "", "one": "总选最常见词义的基线."}, {"id": "baseline.agree", "zh": "上限", "de": "Obergrenze", "one": "人在同一任务上的准确率作为上限."}], "tm": [58, 59], "q": "Baseline: Wähle immer die Lesart, die in den Trainingsdaten am häufigsten war.", "fol": "S. 123"}], "edges": [["tokentype", "zipf", ">", "齐普夫定律统计的是 Type 按 Token 频率的排名.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["zipf", "sparse", ">", "大多数词罕见, 所以大量 n-gram 见不到.", "SMIS-合集-语言处理中的统计方法.html", "korpus"], ["zipf", "absd", ">", "线性折扣不适合齐普夫分布, 才引出绝对折扣.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["null", "binom", ">", "二项检验是零假设检验的一种.", "SMIS-合集-语言处理中的统计方法.html", "tests"], ["binomd", "binom", ">", "二项检验算的就是二项分布的尾部概率.", "SMIS-合集-语言处理中的统计方法.html", "tests"], ["indep", "kolloc", ">", "搭配检验的零假设是两个词统计独立.", "SMIS-合集-语言处理中的统计方法.html", "mathe"], ["binom", "kolloc", ">", "用二项检验判断词对是否显著.", "SMIS-合集-语言处理中的统计方法.html", "kollok"], ["chi", "kolloc", "~", "χ² 是搭配抽取的另一种度量.", "SMIS-合集-语言处理中的统计方法.html", "tests"], ["null", "chi", ">", "χ² 同样用于检验零假设.", "SMIS-合集-语言处理中的统计方法.html", "kollok"], ["mi", "kolloc", "~", "点互信息可以直接当词关联度量.", "SMIS-合集-语言处理中的统计方法.html", "kollok"], ["cond", "chain", ">", "链式法则由条件概率定义反复展开.", "SMIS-合集-语言处理中的统计方法.html", "mathe"], ["cond", "bayes", ">", "贝叶斯定理由条件概率定义推出.", "SMIS-合集-语言处理中的统计方法.html", "mathe"], ["chain", "markov", ">", "先用链式法则分解, 再加马尔可夫假设.", "SMIS-合集-语言处理中的统计方法.html", "markow"], ["bayes", "nbwsd", ">", "用贝叶斯定理把 p(s|C) 转成 p(s) p(C|s).", "SMIS-合集-语言处理中的统计方法.html", "mathe"], ["bayes", "hmm", ">", "词性标注把后验换成联合概率.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["indep", "nbwsd", ">", "上下文词独立就是「朴素」的含义.", "SMIS-合集-语言处理中的统计方法.html", "nb"], ["entropy", "condh", ">", "联合熵和条件熵都由熵推广.", "SMIS-合集-语言处理中的统计方法.html", "info"], ["condh", "mi", ">", "互信息 = 熵 − 条件熵.", "SMIS-合集-语言处理中的统计方法.html", "info"], ["entropy", "xent", ">", "交叉熵 = 熵 + KL 距离.", "SMIS-合集-语言处理中的统计方法.html", "info"], ["kl", "xent", "~", "两者只差 p 的熵.", "SMIS-合集-语言处理中的统计方法.html", "info"], ["kl", "mi", "~", "互信息是联合分布与独立分布之间的 KL 距离.", "SMIS-合集-语言处理中的统计方法.html", "info"], ["xent", "gold", "~", "语言模型用测试数据上的交叉熵比较好坏.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["mlest", "sparse", ">", "最大似然给没见过的事件概率 0.", "SMIS-合集-语言处理中的统计方法.html", "markow"], ["markov", "sparse", ">", "阶数越高越稀疏.", "SMIS-合集-语言处理中的统计方法.html", "markow"], ["sparse", "addk", ">", "平滑是数据稀疏的对策.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["addk", "absd", ">", "从线性折扣改进到绝对折扣.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["absd", "backoff", ">", "Katz 把绝对折扣和回退结合起来.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["backoff", "kn", ">", "Kneser-Ney 改进回退分布本身.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["markov", "hmm", ">", "HMM 的词性序列就是一个马尔可夫模型.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["unk", "backoff", "~", "后缀概率用回退平滑逐级估计.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["hmm", "viterbi", ">", "Viterbi 解 HMM 的最佳序列问题.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["hmm", "fb", ">", "Forward-Backward 算 HMM 的期望频率.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["hmm", "unk", ">", "HMM 的词汇概率必须能处理未知词.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["fb", "em", ">", "EM 的 E 步用 Forward-Backward.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["mlest", "em", ">", "EM 的 M 步用相对频率重估参数.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["pcfg", "treebank", ">", "PCFG 的规则概率可以从树库估计.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["pcfg", "forest", ">", "森林让最佳树的计算不用列举.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["viterbi", "forest", ">", "把 Viterbi 从序列推广到森林上.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["forest", "io", ">", "Inside-Outside 在森林上计算.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["fb", "io", "~", "Inside-Outside 是 PCFG 版的 Forward-Backward.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["em", "io", ">", "Inside-Outside 给 EM 提供期望频率.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["pcfg", "refine", ">", "独立性假设太强, 才要细化范畴.", "SMIS-合集-语言处理中的统计方法.html", "berkeley"], ["refine", "berkeley", ">", "Berkeley 把手工细化变成自动学习.", "SMIS-合集-语言处理中的统计方法.html", "berkeley"], ["em", "berkeley", ">", "每轮分裂后都用 EM 训练.", "SMIS-合集-语言处理中的统计方法.html", "berkeley"], ["generative", "linclf", ">", "判别模型通常是线性打分.", "SMIS-合集-语言处理中的统计方法.html", "diskr"], ["linclf", "perceptron", ">", "感知机用来训练线性分类器.", "SMIS-合集-语言处理中的统计方法.html", "perz"], ["linclf", "loglin", ">", "对数线性模型把线性分数转成概率.", "SMIS-合集-语言处理中的统计方法.html", "loglin"], ["loglin", "grad", ">", "对数似然用梯度上升最大化.", "SMIS-合集-语言处理中的统计方法.html", "loglin"], ["grad", "reg", ">", "目标函数里加正则项.", "SMIS-合集-语言处理中的统计方法.html", "loglin"], ["loglin", "crf", ">", "CRF 是用于序列的对数线性模型.", "SMIS-合集-语言处理中的统计方法.html", "crf"], ["viterbi", "crf", ">", "CRF 解码也用 Viterbi.", "SMIS-合集-语言处理中的统计方法.html", "crf"], ["fb", "crf", ">", "梯度里的期望频率用 Forward-Backward 算.", "SMIS-合集-语言处理中的统计方法.html", "crf"], ["hmm", "generative", "~", "HMM 是典型的生成模型, 新信息很难加入.", "SMIS-合集-语言处理中的统计方法.html", "perz"], ["nbwsd", "linclf", "~", "朴素贝叶斯也可以写成线性分类器.", "SMIS-合集-语言处理中的统计方法.html", "glaett"], ["perceptron", "crf", "~", "更新形式相似, 比较值不同: 最优序列 vs. 期望值.", "SMIS-合集-语言处理中的统计方法.html", "crf"], ["gold", "prf", ">", "精确率和召回率都对照金标准.", "SMIS-合集-语言处理中的统计方法.html", "pcfg"], ["baseline", "nbwsd", "~", "词义消歧用最常见读法作基线.", "SMIS-合集-语言处理中的统计方法.html", "nb"], ["sign", "gold", "~", "比较两个标注器时, 看差别是否显著.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["null", "sign", ">", "符号检验也是零假设检验.", "SMIS-合集-语言处理中的统计方法.html", "hmm"], ["binomd", "sign", ">", "符号检验的概率用二项分布算."]], "terms": [{"t": "Korpus", "zh": "语料库", "b": "korp", "d": "Sammlung von Texten für linguistische Zwecke.", "zd": "为语言学目的收集的文本集合.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "q": "Korpus: Sammlung von Texten für linguistische Zwecke", "fol": "S. 9", "art": "das", "dsrc": "Duden", "pl": "Korpora"}, {"t": "Token", "zh": "词次", "b": "korp", "d": "Einzelnes Vorkommen eines Wortes im Text.", "zd": "一个词在文本里的每次出现.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "vs": "Type", "art": "das", "dsrc": "Duden", "pl": "Tokens", "n": "tokentype"}, {"t": "Type", "zh": "词型", "b": "korp", "d": "Unterschiedliche Wortform; jede wird nur einmal gezählt.", "zd": "不同的词, 同形只算一次.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "q": "Zahl der unterschiedlichen Wörter: 8018 (Types)", "fol": "S. 9", "vs": "Token", "art": "der", "dsrc": "DWDS", "pl": "Types", "n": "tokentype"}, {"t": "Hapax Legomenon", "zh": "孤例词", "b": "korp", "d": "Wort, das im Korpus genau einmal vorkommt.", "zd": "语料里只出现一次的词.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "q": "Zahl der Wörter, die einmal auftraten: 3993 (Hapax Legomena)", "fol": "S. 9", "alt": ["Hapax Legomena"], "n": "tokentype", "ns": "tokentype.hapax"}, {"t": "Zipf’sches Gesetz", "zh": "齐普夫定律", "b": "korp", "d": "Die Häufigkeit eines Wortes ist umgekehrt proportional zu seinem Rang.", "zd": "词频与排名成反比.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "alt": ["Zipfsches Gesetz"], "art": "das", "dsrc": "Duden", "n": "zipf"}, {"t": "Nullhypothese", "zh": "零假设", "b": "korp", "d": "Annahme, die ein statistischer Test zu widerlegen versucht.", "zd": "统计检验想要推翻的假设.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "q": "Nullhypothese: Die Wahrscheinlichkeit von “Kopf” ist 0.5.", "fol": "S. 52", "art": "die", "dsrc": "Duden", "pl": "Nullhypothesen", "n": "null"}, {"t": "Binomialtest", "zh": "二项检验", "b": "korp", "d": "Test, der die Wahrscheinlichkeit einer beobachteten Trefferzahl mit der Binomialverteilung berechnet.", "zd": "用二项分布计算观察到的次数有多不可能.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "q": "Beim Binomialtest gibt der berechnete Wert direkt die Wahrscheinlichkeit (= p-Wert) dafür an, einen Fehler zu machen, wenn wir die Nullhypothese zurückweisen.", "fol": "S. 67", "vs": "χ²-Test", "art": "der", "dsrc": "课件", "n": "binom"}, {"t": "Kollokation", "zh": "搭配", "b": "korp", "d": "Feste Wortverbindung, die häufiger auftritt, als bei statistischer Unabhängigkeit zu erwarten wäre.", "zd": "比统计独立时预期更常见的固定词组合.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "q": "Kollokationen sind feste Wortkombinationen, die beim Erwerb einer Sprache gelernt werden müssen.", "fol": "S. 57–58", "art": "die", "dsrc": "Duden", "pl": "Kollokationen", "n": "kolloc"}, {"t": "Kontingenztabelle", "zh": "列联表", "b": "korp", "d": "Tabelle mit den beobachteten Häufigkeiten aller Kombinationen zweier Merkmale.", "zd": "记录两个属性各种组合的观察频数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "art": "die", "dsrc": "DWDS", "pl": "Kontingenztabellen", "n": "chi", "ns": "chi.ctab"}, {"t": "p-Wert", "zh": "p 值", "b": "korp", "d": "Irrtumswahrscheinlichkeit beim Verwerfen der Nullhypothese.", "zd": "拒绝零假设时犯错的概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "q": "Wie die Ergebnisse zeigen, können sich die p-Werte verschiedener statistischer Tests deutlich unterscheiden.", "fol": "S. 67", "art": "der", "dsrc": "Duden", "pl": "p-Werte", "n": "null", "ns": "null.pval"}, {"t": "Zufallsexperiment", "zh": "随机试验", "b": "prob", "d": "Experiment mit mehreren möglichen Ergebnissen.", "zd": "有多种可能结果的试验.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Zufallsexperiment: Experiment (Versuch) mit mehreren möglichen Ausgängen (z.B. Wurf von zwei Würfeln)", "fol": "S. 15–16", "art": "das", "dsrc": "Duden", "pl": "Zufallsexperimente", "n": "cond", "ns": "cond.sample"}, {"t": "Ergebnisraum", "zh": "样本空间", "b": "prob", "d": "Menge aller möglichen Ergebnisse eines Zufallsexperiments.", "zd": "一次试验所有可能结果的集合.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Ergebnisraum Ω: Menge aller möglichen Ergebnisse (hier {(1,1),(1,2),(1,3),(1,4),(1,5),(1,6),(2,1),..,(6,6)})", "fol": "S. 15–16", "vs": "Ereignis", "n": "cond", "ns": "cond.sample"}, {"t": "Ereignis", "zh": "事件", "b": "prob", "d": "Teilmenge des Ergebnisraums.", "zd": "样本空间的子集.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "vs": "Ergebnisraum", "art": "das", "dsrc": "Duden", "pl": "Ereignisse", "n": "cond", "ns": "cond.sample"}, {"t": "Wahrscheinlichkeitsverteilung", "zh": "概率分布", "b": "prob", "d": "Funktion, die jedem Ergebnis einen Wert zwischen 0 und 1 zuweist; alle Werte summieren sich zu 1.", "zd": "给每个结果一个 0 到 1 的值, 总和为 1.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "art": "die", "dsrc": "DWDS", "pl": "Wahrscheinlichkeitsverteilungen", "n": "cond"}, {"t": "bedingte Wahrscheinlichkeit", "zh": "条件概率", "b": "prob", "d": "Wahrscheinlichkeit von A, wenn bekannt ist, dass B eingetreten ist.", "zd": "已知 B 发生时 A 的概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "art": "die", "dsrc": "Duden", "pl": "bedingte Wahrscheinlichkeiten", "n": "cond"}, {"t": "Zufallsvariable", "zh": "随机变量", "b": "prob", "d": "Funktion, die jedem Ergebnis eine reelle Zahl zuweist.", "zd": "给每个结果指派一个实数的函数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Zufallsvariable: Funktion, welche jedem Ergebnis eine reelle Zahl zuweist.", "fol": "S. 21", "art": "die", "dsrc": "Duden", "pl": "Zufallsvariablen", "n": "binomd", "ns": "binomd.randvar"}, {"t": "Erwartungswert", "zh": "期望值", "b": "prob", "d": "Gewichteter Mittelwert einer Zufallsvariablen.", "zd": "随机变量的加权平均.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "vs": "Varianz", "art": "der", "dsrc": "DWDS", "pl": "Erwartungswerte", "n": "binomd", "ns": "binomd.ev"}, {"t": "Varianz", "zh": "方差", "b": "prob", "d": "Erwartete quadratische Abweichung vom Mittelwert.", "zd": "偏差平方的期望.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "vs": "Erwartungswert", "art": "die", "dsrc": "Duden", "pl": "Varianzen", "n": "binomd", "ns": "binomd.ev"}, {"t": "Randverteilung", "zh": "边缘分布", "b": "prob", "d": "Verteilung einer Variablen, die man durch Summieren über die andere Variable aus der gemeinsamen Verteilung erhält.", "zd": "对另一个变量求和得到的分布.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "art": "die", "dsrc": "Duden", "pl": "Randverteilungen", "n": "cond", "ns": "cond.marg"}, {"t": "Kettenregel", "zh": "链式法则", "b": "prob", "d": "Zerlegung einer gemeinsamen Wahrscheinlichkeit in ein Produkt bedingter Wahrscheinlichkeiten.", "zd": "把联合概率拆成条件概率的乘积.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Problem: Die Kettenregel ist eigentlich nur anwendbar, wenn alle Texte dieselbe Länge n besitzen.", "fol": "S. 76", "art": "die", "dsrc": "Duden", "pl": "Kettenregeln", "n": "chain"}, {"t": "Binomialverteilung", "zh": "二项分布", "b": "prob", "d": "Verteilung der Trefferzahl bei n unabhängigen Bernoulli-Experimenten.", "zd": "n 次独立伯努利试验的命中次数分布.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "art": "die", "dsrc": "Duden", "pl": "Binomialverteilungen", "n": "binomd"}, {"t": "relative Häufigkeit", "zh": "相对频率", "b": "prob", "d": "Anzahl der Vorkommen eines Ereignisses geteilt durch die Stichprobengröße.", "zd": "事件次数除以样本大小.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "art": "die", "dsrc": "Duden", "pl": "relative Häufigkeiten", "n": "mlest"}, {"t": "Maximum-Likelihood-Schätzung", "zh": "最大似然估计", "b": "prob", "d": "Schätzung der Parameter, unter denen die Trainingsdaten am wahrscheinlichsten sind.", "zd": "选使训练数据概率最大的参数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "q": "Dies ist die Maximum-Likelihood-Schätzung (MLE) bzgl. der Trainingsdaten. Keine andere Wahl der Parameter weist den Trainingsdaten eine höhere Wahrscheinlichkeit zu.", "fol": "S. 85–86", "art": "die", "dsrc": "Duden", "pl": "Maximum-Likelihood-Schätzungen", "n": "mlest"}, {"t": "Entropie", "zh": "熵", "b": "info", "d": "Durchschnittlicher Informationsgehalt eines Zufallsereignisses.", "zd": "随机事件平均提供的信息量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "Die Entropie misst, wieviel Information ein Zufallsereignis im Mittel liefert.", "fol": "S. 37", "vs": "Crossentropie", "art": "die", "dsrc": "Duden", "pl": "Entropien", "n": "entropy"}, {"t": "bedingte Entropie", "zh": "条件熵", "b": "info", "d": "Verbleibende Unsicherheit über Y, wenn X bekannt ist.", "zd": "已知 X 后 Y 剩下的不确定性.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "art": "die", "dsrc": "Duden", "pl": "bedingte Entropien", "n": "condh"}, {"t": "Mutual Information", "zh": "互信息", "b": "info", "d": "Maß dafür, wie viel Information zwei Zufallsvariablen gemeinsam haben.", "zd": "两个随机变量共享的信息量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "Die Mutual Information I(X; Y) ist die “Schnittmenge” der Informationgehalte der beiden Zufallsvariablen X unf Y.", "fol": "S. 44", "art": "die", "dsrc": "Duden", "n": "mi"}, {"t": "Relative Entropie", "zh": "相对熵", "b": "info", "d": "Nichtsymmetrisches Abstandsmaß zwischen zwei Wahrscheinlichkeitsverteilungen.", "zd": "两个分布之间不对称的差异度量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "Die relative Entropie gibt an, wieviele Bits im Mittel verschenkt werden, wenn Ereignisse mit einer Verteilung p mit einem Code kodiert werden, der optimal für die Verteilung q ist.", "fol": "S. 47", "vs": "Crossentropie", "alt": ["KL-Distanz"], "art": "die", "dsrc": "Duden", "pl": "relative Entropien", "n": "kl"}, {"t": "Crossentropie", "zh": "交叉熵", "b": "info", "d": "Entropie von p plus der relativen Entropie zwischen p und q.", "zd": "p 的熵加上 p 和 q 的 KL 距离.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "Das Modell mit der geringsten Crossentropie/Perplexität ist das beste.", "fol": "S. 106", "vs": "Entropie", "alt": ["Kreuzentropie"], "art": "die", "dsrc": "DWDS", "pl": "Crossentropien", "n": "xent"}, {"t": "Perplexität", "zh": "困惑度", "b": "info", "d": "Zwei hoch Crossentropie; misst die Qualität eines Sprachmodells auf Testdaten.", "zd": "2 的交叉熵次方, 用来评价语言模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "Das Modell mit der geringsten Crossentropie/Perplexität ist das beste.", "fol": "S. 106", "art": "die", "dsrc": "Duden", "n": "xent"}, {"t": "Sprachmodell", "zh": "语言模型", "b": "lm", "d": "Wahrscheinlichkeitsverteilung über Wort- oder Zeichenfolgen.", "zd": "词序列或字符序列上的概率分布.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "q": "Sprachmodelle werden oft in der Sprachverarbeitung verwendet (Spracherkennung, maschinelle Übersetzung, Sprachidentifizierung).", "fol": "S. 71–73", "art": "das", "dsrc": "Duden", "pl": "Sprachmodelle", "n": "markov"}, {"t": "Markowmodell", "zh": "马尔可夫模型", "b": "lm", "d": "Modell, bei dem ein Symbol nur von den k vorhergehenden Symbolen abhängt.", "zd": "符号只依赖前 k 个符号的模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "q": "Ein solches Modell heißt Markowmodell der Ordnung k.", "fol": "S. 78", "vs": "Hidden-Markow-Modell", "alt": ["Markov-Modell"], "art": "das", "dsrc": "Duden", "pl": "Markowmodelle", "n": "markov"}, {"t": "Parameterglättung", "zh": "参数平滑", "b": "lm", "d": "Verfahren, das unbeobachteten Ereignissen eine Wahrscheinlichkeit größer null gibt.", "zd": "让没见过的事件概率大于零的方法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "q": "Prinzip der Parameterglättung: Man nimmt den beobachteten n-Grammen etwas Wahrscheinlichkeit weg und verteilt sie an die nicht beobachteten n-Gramme.", "fol": "S. 87", "art": "die", "dsrc": "DWDS", "n": "sparse", "ns": "sparse.tradeoff"}, {"t": "Absolute Discounting", "zh": "绝对折扣", "b": "lm", "d": "Von jeder beobachteten Häufigkeit wird ein fester Wert abgezogen und auf unbeobachtete Ereignisse verteilt.", "zd": "每个频率减去固定值, 分给没见过的事件.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "n": "absd"}, {"t": "Backoff-Faktor", "zh": "回退因子", "b": "lm", "d": "Gewicht, mit dem die Wahrscheinlichkeit aus dem kürzeren Kontext eingeht.", "zd": "短上下文概率的权重.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "vs": "Backoff-Verteilung", "art": "der", "dsrc": "Duden", "pl": "Backoff-Faktoren", "n": "backoff", "ns": "backoff.bofactor"}, {"t": "Backoff-Verteilung", "zh": "回退分布", "b": "lm", "d": "Verteilung aus dem kürzeren Kontext, auf die man bei fehlender Evidenz zurückgreift.", "zd": "长上下文没见过时使用的分布.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "vs": "Backoff-Faktor", "art": "die", "dsrc": "Duden", "pl": "Backoff-Verteilungen", "n": "backoff"}, {"t": "Hyperparameter", "zh": "超参数", "b": "lm", "d": "Parameter wie die Modellordnung, der nicht aus den Trainingsdaten geschätzt wird.", "zd": "不从训练数据估计的参数, 如模型阶数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "q": "In der Praxis ist k ein Hyperparameter, der auf Development-Daten optimiert werden kann.", "fol": "S. 79", "vs": "Metaparameter", "art": "der", "dsrc": "DWDS", "pl": "Hyperparameter", "n": "gold", "ns": "gold.meta"}, {"t": "Wortbedeutungs-Desambiguierung", "zh": "词义消歧", "b": "tag", "d": "Bestimmung der im Kontext richtigen Lesart eines mehrdeutigen Wortes.", "zd": "确定歧义词在上下文里的正确读法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "nb", "q": "Wir werden nun ein statistisches Modell für die Wortbedeutungs-Desambiguierung betrachten, welches als wesentliche Information die in der Nähe des mehrdeutigen Wortes aufgetretenen Inhaltswörter benutzt.", "fol": "S. 114", "art": "die", "dsrc": "课件", "n": "nbwsd"}, {"t": "Pseudowort", "zh": "伪词", "b": "tag", "d": "Künstlich mehrdeutiges Wort aus zwei zusammengelegten Wörtern, das Evaluierungsdaten erzeugt.", "zd": "把两个词合并造出的人工歧义词, 用来生成评估数据.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "nb", "art": "das", "dsrc": "Wiktionary", "pl": "Pseudowörter", "n": "nbwsd", "ns": "nbwsd.pseudo"}, {"t": "Hidden-Markow-Modell", "zh": "隐马尔可夫模型", "b": "tag", "d": "Modell mit verborgener Tagfolge, aus der die Wörter emittiert werden.", "zd": "词由隐藏的标签序列发射出来的模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Dieses Modell heißt Hidden-Markow-Modell, weil die Zustände (Tags bzw. Tagpaare beim Trigramm-Tagger) nicht direkt beobachtbar sind.", "fol": "S. 129", "vs": "Markowmodell", "alt": ["Hidden-Markov-Modell"], "art": "das", "dsrc": "Duden", "pl": "Hidden-Markow-Modelle", "n": "hmm"}, {"t": "Kontextwahrscheinlichkeit", "zh": "上下文概率", "b": "tag", "d": "Wahrscheinlichkeit eines Tags gegeben die vorhergehenden Tags.", "zd": "给定前面的标签时当前标签的概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Die Kontextwahrscheinlichkeiten erfassen die syntaktischen Abhängigkeiten der Wortart-Tags vom linken Satzkontext.", "fol": "S. 131", "vs": "lexikalische Wahrscheinlichkeit", "art": "die", "dsrc": "DWDS", "pl": "Kontextwahrscheinlichkeiten", "n": "hmm", "ns": "hmm.ctxprob"}, {"t": "lexikalische Wahrscheinlichkeit", "zh": "词汇概率", "b": "tag", "d": "Wahrscheinlichkeit eines Wortes gegeben sein Tag.", "zd": "给定标签时词的概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "vs": "Kontextwahrscheinlichkeit", "art": "die", "dsrc": "Duden", "pl": "lexikalische Wahrscheinlichkeiten", "n": "hmm", "ns": "hmm.lexprob"}, {"t": "Viterbi-Algorithmus", "zh": "Viterbi 算法", "b": "tag", "d": "Dynamische Programmierung zur Berechnung der wahrscheinlichsten Tagfolge.", "zd": "用动态规划计算最可能的标签序列.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "vs": "Forward-Backward-Algorithmus", "art": "der", "dsrc": "Duden", "pl": "Viterbi-Algorithmen", "n": "viterbi"}, {"t": "Forward-Backward-Algorithmus", "zh": "前向后向算法", "b": "tag", "d": "Berechnet erwartete Tag-Häufigkeiten mit dynamischer Programmierung.", "zd": "用动态规划计算期望标签频率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Berechnung der erwarteten Wort-Tag- und Tag-Tag-Häufigkeiten mit dem Forward-Backward-Algorithmus (E-Schritt)", "fol": "S. 168", "vs": "Viterbi-Algorithmus", "art": "der", "dsrc": "Duden", "pl": "Forward-Backward-Algorithmen", "n": "fb"}, {"t": "erwartete Häufigkeit", "zh": "期望频率", "b": "tag", "d": "Häufigkeit, gewichtet mit der Wahrscheinlichkeit der Analysen, statt direkt gezählt.", "zd": "按分析的概率加权的频率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "alt": ["erwartete Häufigkeiten"], "art": "die", "dsrc": "Duden", "pl": "erwartete Häufigkeiten", "n": "chi", "ns": "chi.expect"}, {"t": "Parsewald", "zh": "分析森林", "b": "parse", "d": "Kompakte Repräsentation aller Analysen eines Satzes.", "zd": "一个句子所有分析的紧凑表示.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "art": "der", "dsrc": "DWDS", "pl": "Parsewälder", "n": "forest"}, {"t": "Baumbank", "zh": "树库", "b": "parse", "d": "Korpus, dessen Sätze manuell mit Parsebäumen annotiert sind.", "zd": "句子都人工标注了分析树的语料.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Baumbanken müssen manuell erstellt werden.", "fol": "S. 189", "art": "die", "dsrc": "DWDS", "pl": "Baumbanken", "n": "treebank"}, {"t": "Linksableitung", "zh": "最左推导", "b": "parse", "d": "Ableitung, die immer das am weitesten links stehende Nichtterminal expandiert.", "zd": "每步都展开最左边的非终端符号.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Zu jeder (partiellen) Linksableitung gibt es einen eindeutigen (partiellen) Parsebaum und umgekehrt.", "fol": "S. 183", "art": "die", "dsrc": "DWDS", "pl": "Linksableitungen", "n": "pcfg", "ns": "pcfg.deriv"}, {"t": "Elternannotation", "zh": "父节点标注", "b": "parse", "d": "Jeder Knoten wird zusätzlich mit der Kategorie seines Elternknotens annotiert.", "zd": "每个节点额外标上父节点的范畴.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "berkeley", "art": "die", "dsrc": "DWDS", "pl": "Elternannotationen", "n": "refine", "ns": "refine.parent"}, {"t": "Markowisierung", "zh": "马尔可夫化", "b": "parse", "d": "Lange Regeln werden binarisiert; Hilfssymbole merken sich nur einen Teil des Kontexts.", "zd": "把长规则二元化, 辅助范畴只记部分上下文.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "berkeley", "q": "Die gezeigte Markowisierung ist äquivalent dazu, dass wir die rechten Seiten (und Wahrscheinlichkeiten) von bspw. NP-Regeln mit einem Markow-Modell 2. Ordnung erzeugen.", "fol": "S. 247", "art": "die", "dsrc": "课件", "n": "refine", "ns": "refine.markovize"}, {"t": "Merkmalsfunktion", "zh": "特征函数", "b": "disc", "d": "Funktion, die einem Objekt einen Zahlenwert zuordnet, oft binär.", "zd": "给对象一个数值的函数, 常为二值.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "q": "Manuell erstellte Merkmalsfunktionen extrahieren relevante Information aus dem Dokumentz.B. das Vorkommen eines Wortes wie “Lotterie”.", "fol": "S. 261", "art": "die", "dsrc": "DWDS", "pl": "Merkmalsfunktionen", "n": "generative", "ns": "generative.feat"}, {"t": "generatives Modell", "zh": "生成模型", "b": "disc", "d": "Modell, das die gemeinsame Wahrscheinlichkeit von Eingabe und Klasse definiert.", "zd": "定义输入和类别联合概率的模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "q": "Alle bisher betrachteten Modelle (Markowodell, Naïve-Bayes-Modell, HMM, PCFG) sind generative Modelle.", "fol": "S. 257–258", "vs": "diskriminatives Modell", "alt": ["generative Modelle"], "art": "das", "dsrc": "Duden", "pl": "generative Modelle", "n": "generative"}, {"t": "diskriminatives Modell", "zh": "判别模型", "b": "disc", "d": "Modell, das die bedingte Wahrscheinlichkeit der Klasse gegeben das Objekt definiert.", "zd": "定义给定对象时类别条件概率的模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "q": "Diskriminative Modelle definieren eine bedingte Wahrscheinlichkeit p(c|d) für die Klassen c gegeben ein Objekt d.", "fol": "S. 260", "vs": "generatives Modell", "alt": ["diskriminative Modelle"], "art": "das", "dsrc": "Duden", "pl": "diskriminative Modelle", "n": "generative"}, {"t": "Perzeptron", "zh": "感知机", "b": "disc", "d": "Trainingsverfahren, das die Gewichte nur bei Fehlklassifikation anpasst.", "zd": "只在分错时调整权重的训练方法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "perz", "q": "Diese Methode wendet der Perzeptron-Algorithmus an, den wir als Nächstes behandeln. Später werden wir sehen, wie man den Score in eine Wahrscheinlichkeit transformiert (⇒ log-lineare Modelle).", "fol": "S. 265", "n": "perceptron"}, {"t": "log-lineares Modell", "zh": "对数线性模型", "b": "disc", "d": "Modell, das lineare Scores per Exponentialfunktion und Normalisierung in Wahrscheinlichkeiten umwandelt.", "zd": "用指数和归一化把线性分数变成概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "q": "Ein solches Modell heißt log-lineares Modell.", "fol": "S. 279", "alt": ["log-lineare Modelle"], "art": "das", "dsrc": "Duden", "pl": "log-lineare Modelle", "n": "loglin"}, {"t": "Gradientenanstieg", "zh": "梯度上升", "b": "disc", "d": "Parameter werden schrittweise in Richtung des Gradienten verändert.", "zd": "沿梯度方向逐步修改参数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "art": "der", "dsrc": "DWDS", "pl": "Gradientenanstiege", "n": "grad"}, {"t": "Regularisierung", "zh": "正则化", "b": "disc", "d": "Bestrafung großer Gewichte, um Overfitting zu vermeiden.", "zd": "惩罚大权重以避免过拟合.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "q": "µ bestimmt, wie stark regularisiert wird. Keine Regularisierung für µ = 0. µ kann auf Development-Daten optimiert werden und hat einen Wert ≥ 0 und (normalerweise) < 1.", "fol": "S. 291", "vs": "Overfitting", "art": "die", "dsrc": "DWDS", "pl": "Regularisierungen", "n": "reg"}, {"t": "Overfitting", "zh": "过拟合", "b": "disc", "d": "Das Modell passt sich zu stark an die Trainingsdaten an.", "zd": "模型过度适应训练数据.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "perz", "q": "Aber dadurch wird der Gewichtsvektor zu stark an die Trainingsdaten angepasst (Overfitting).", "fol": "S. 276", "vs": "Regularisierung", "art": "das", "dsrc": "Duden", "n": "reg"}, {"t": "Goldstandard", "zh": "金标准", "b": "eval", "d": "Manuell erstellte, als korrekt geltende Referenzannotation.", "zd": "人工建立、被视为正确的参照标注.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "art": "der", "dsrc": "Duden", "pl": "Goldstandards", "n": "gold"}, {"t": "Baseline", "zh": "基线", "b": "eval", "d": "Einfaches Vergleichsverfahren, das ein System mindestens schlagen muss.", "zd": "系统至少要超过的简单比较方法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "nb", "q": "Baseline: Wähle immer die Lesart, die in den Trainingsdaten am häufigsten war.", "fol": "S. 123", "vs": "Obergrenze", "art": "die", "dsrc": "Duden", "pl": "Baselines", "n": "baseline"}, {"t": "Obergrenze", "zh": "上限", "b": "eval", "d": "Maximal erreichbare Leistung, oft die Übereinstimmung menschlicher Annotatoren.", "zd": "能达到的最高水平, 常取人工标注者一致率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "nb", "q": "Wenn man wissen möchte, wie weit die Klassifizierungsgenauigkeit noch gesteigert werden kann, kann man die Genauigkeit, die ein Mensch bei der Aufgabe erreicht, als Obergrenze zum Vergleich heranziehen.", "fol": "S. 123", "vs": "Baseline", "art": "die", "dsrc": "Duden", "pl": "Obergrenzen", "n": "baseline"}, {"t": "Vorzeichentest", "zh": "符号检验", "b": "eval", "d": "Signifikanztest, der nur Fälle betrachtet, in denen genau ein System falsch liegt.", "zd": "只看恰好一个系统出错的情况的显著性检验.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Dazu wenden wir einen Signifikanztest an. Wir werden den Vorzeichentest nehmen.", "fol": "S. 150", "art": "der", "dsrc": "DWDS", "pl": "Vorzeichentests", "n": "sign"}, {"t": "Metaparameter", "zh": "元参数", "b": "eval", "d": "Frei wählbarer Parameter eines Systems, der auf Entwicklungsdaten optimiert wird.", "zd": "系统中可任选、在开发数据上优化的参数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Der beschriebene HMM-Tagger hat eine Reihe von Metaparametern (Ordnung des Modelles n, maximale Suffixlänge l), die beliebig gewählt werden können.", "fol": "S. 152", "vs": "Hyperparameter", "art": "der", "dsrc": "Duden", "pl": "Metaparameter", "n": "gold", "ns": "gold.meta"}, {"t": "Entwicklungsdaten", "zh": "开发数据", "b": "eval", "d": "Separate Daten zur Optimierung von Metaparametern, getrennt von den Testdaten.", "zd": "用于调元参数的数据, 与测试数据分开.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Solche Daten für die Parameter-Optimierung nennt man Entwicklungsdaten (Developmentdaten).", "fol": "S. 152", "n": "gold", "ns": "gold.dev"}, {"t": "Precision", "zh": "精确率", "b": "eval", "d": "Anteil der korrekten Konstituenten an allen ausgegebenen.", "zd": "输出成分里正确的比例.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "vs": "Recall", "art": "die", "dsrc": "课件", "n": "prf"}, {"t": "Recall", "zh": "召回率", "b": "eval", "d": "Anteil der gefundenen Konstituenten an allen im Goldstandard.", "zd": "金标准成分里被找到的比例.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Mit dem Recall messen wir zusätzlich, wieviel Prozent der Goldstandard-Konstituenten im Parse enthalten waren. Zusammen ergeben Precision und Recall ein genaues Bild der Parsing-Genauigkeit.", "fol": "S. 225", "vs": "Precision", "art": "der", "dsrc": "Duden", "pl": "Recalls", "n": "prf"}, {"t": "Type-Token-Verhältnis", "zh": "词型词次比", "b": "korp", "d": "Anzahl der Types geteilt durch die Anzahl der Tokens.", "zd": "Type 数除以 Token 数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "vs": "Token; Type", "alt": ["TTR"], "art": "das", "dsrc": "Duden", "pl": "Type-Token-Verhältnisse", "n": "tokentype", "ns": "tokentype.ttr"}, {"t": "Zipf’sche Verteilung", "zh": "齐普夫分布", "b": "korp", "d": "Verteilung, bei der die Häufigkeit umgekehrt proportional zum Rang ist.", "zd": "频率与排名成反比的分布.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "vs": "Zipf’sches Gesetz", "art": "die", "dsrc": "Duden", "pl": "Zipf’sche Verteilungen", "n": "zipf"}, {"t": "Häufigkeit zweiter Ordnung", "zh": "二阶频率", "b": "korp", "d": "Anzahl der Types, die genau r-mal vorkommen (N_r).", "zd": "恰好出现 r 次的 Type 有多少个.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "korpus", "alt": ["N_r"], "art": "die", "dsrc": "Duden", "pl": "Häufigkeiten zweiter Ordnung", "n": "tokentype", "ns": "tokentype.freq2"}, {"t": "Signifikanzniveau", "zh": "显著性水平", "b": "korp", "d": "Vorab festgelegte Schranke für den p-Wert, meist 0,05.", "zd": "事先定好的 p 值阈值, 常为 0.05.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "vs": "p-Wert", "art": "das", "dsrc": "DWDS", "pl": "Signifikanzniveaus", "n": "null", "ns": "null.alpha"}, {"t": "Signifikanz", "zh": "显著性", "b": "korp", "d": "Ein Ergebnis ist signifikant, wenn es unter der Nullhypothese sehr unwahrscheinlich ist.", "zd": "结果在零假设下极不可能出现, 就算显著.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "alt": ["signifikant"], "art": "die", "dsrc": "Duden", "pl": "Signifikanzen", "n": "null"}, {"t": "Stichprobe", "zh": "样本", "b": "korp", "d": "Beobachtete Teilmenge, aus der auf die Gesamtheit geschlossen wird.", "zd": "用来推断总体的观察子集.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "q": "Mit einer größeren Stichprobe wäre eventuell ein signifikantes Ergebnis erzielt worden.", "fol": "S. 56", "art": "die", "dsrc": "Duden", "pl": "Stichproben", "n": "null"}, {"t": "Kollokationsextraktion", "zh": "搭配抽取", "b": "korp", "d": "Automatisches Finden von Wortpaaren, die überzufällig oft gemeinsam auftreten.", "zd": "自动找出共现次数超出偶然的词对.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "q": "Bei der Kollokationsextraktion suchen wir Wortpaare, die häufiger sind, als auf Grund der Einzelwort-Häufigkeiten zu erwarten wäre.", "fol": "S. 62", "vs": "Kollokation", "art": "die", "dsrc": "DWDS", "pl": "Kollokationsextraktionen", "n": "kolloc"}, {"t": "χ²-Test", "zh": "卡方检验", "b": "korp", "d": "Test, der beobachtete mit erwarteten Häufigkeiten einer Kontingenztabelle vergleicht.", "zd": "比较列联表观察频率与期望频率的检验.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "vs": "Binomialtest", "alt": ["Chi-Quadrat-Test", "Chi²-Test"], "art": "der", "dsrc": "Duden", "pl": "χ²-Tests", "n": "chi"}, {"t": "t-Score", "zh": "t 分数", "b": "korp", "d": "Assoziationsmaß aus der Differenz von beobachtetem und erwartetem Mittel, geteilt durch die Standardabweichung.", "zd": "用均值差除以标准差得到的关联度量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "alt": ["t-Wert"], "art": "der", "dsrc": "Duden", "pl": "t-Scores", "n": "kolloc", "ns": "kolloc.tscore"}, {"t": "Log-Likelihood-Ratio", "zh": "对数似然比", "b": "korp", "d": "Assoziationsmaß, das die Likelihood unter Abhängigkeit und Unabhängigkeit vergleicht.", "zd": "比较相关与独立两种假设下似然的关联度量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "alt": ["LLR", "Likelihood-Ratio"], "n": "kolloc", "ns": "kolloc.llr"}, {"t": "punktweise Mutual Information", "zh": "点互信息", "b": "info", "d": "Logarithmus von p(x,y) geteilt durch p(x)p(y) für ein einzelnes Ereignispaar.", "zd": "单个事件对上 p(x,y) 与 p(x)p(y) 之比的对数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "kollok", "q": "Beispiel: Punktweise Mutual Information zwischen den Wörtern des Wort-Bigrammes (Bayern, München):I(Bayern;München) = log₂ p(Bayern,München) / [p(Bayern) p(München)]", "fol": "S. 45", "vs": "Mutual Information", "alt": ["PMI", "Pointwise Mutual Information"], "art": "die", "dsrc": "Duden", "n": "kolloc", "ns": "kolloc.pmi"}, {"t": "Elementarereignis", "zh": "基本事件", "b": "prob", "d": "Einzelnes Ergebnis eines Zufallsexperiments.", "zd": "随机试验的单个结果.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Elementarereignis: anderes Wort für Ergebnis", "fol": "S. 15–16", "vs": "Ereignis", "art": "das", "dsrc": "Duden", "pl": "Elementarereignisse", "n": "cond", "ns": "cond.sample"}, {"t": "gemeinsame Verteilung", "zh": "联合分布", "b": "prob", "d": "Wahrscheinlichkeitsverteilung über mehrere Zufallsvariablen zugleich.", "zd": "多个随机变量同时取值的概率分布.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Bei einem fairen Würfel erhalten wir die gemeinsame Verteilung: (X, Y, p(x,y)) = (0,0,2/6), (0,1,1/6), (1,0,1/6), (1,1,2/6)", "fol": "S. 40", "vs": "Randverteilung", "art": "die", "dsrc": "Duden", "pl": "gemeinsame Verteilungen", "n": "cond", "ns": "cond.joint"}, {"t": "statistische Unabhängigkeit", "zh": "统计独立", "b": "prob", "d": "Die gemeinsame Wahrscheinlichkeit ist das Produkt der Einzelwahrscheinlichkeiten.", "zd": "联合概率等于各自概率之积.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "alt": ["Unabhängigkeit", "unabhängig"], "art": "die", "dsrc": "Duden", "n": "indep"}, {"t": "Theorem von Bayes", "zh": "贝叶斯定理", "b": "prob", "d": "Formel, die p(x|y) aus p(y|x), p(x) und p(y) berechnet.", "zd": "由 p(y|x)、p(x)、p(y) 算出 p(x|y) 的公式.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "alt": ["Bayes-Theorem", "Satz von Bayes", "Bayes’sches Theorem"], "art": "das", "dsrc": "Duden", "n": "bayes"}, {"t": "A-priori-Wahrscheinlichkeit", "zh": "先验概率", "b": "prob", "d": "Wahrscheinlichkeit einer Hypothese, bevor Daten beobachtet werden.", "zd": "观察数据之前假设的概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Man nennt p(x) auch Apriori- und p(x|y) Aposteriori-Wahrscheinlichkeit.", "fol": "S. 29", "vs": "A-posteriori-Wahrscheinlichkeit", "alt": ["Apriori-Wahrscheinlichkeit", "Apriori"], "art": "die", "dsrc": "Duden", "pl": "A-priori-Wahrscheinlichkeiten", "n": "bayes", "ns": "bayes.prior"}, {"t": "A-posteriori-Wahrscheinlichkeit", "zh": "后验概率", "b": "prob", "d": "Wahrscheinlichkeit einer Hypothese, nachdem Daten beobachtet wurden.", "zd": "观察数据之后假设的概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Man nennt p(x) auch Apriori- und p(x|y) Aposteriori-Wahrscheinlichkeit.", "fol": "S. 29", "vs": "A-priori-Wahrscheinlichkeit", "alt": ["Aposteriori-Wahrscheinlichkeit", "Aposteriori"], "art": "die", "dsrc": "Duden", "pl": "A-posteriori-Wahrscheinlichkeiten", "n": "bayes", "ns": "bayes.prior"}, {"t": "Bernoulli-Experiment", "zh": "伯努利试验", "b": "prob", "d": "Zufallsexperiment mit genau zwei möglichen Ergebnissen.", "zd": "只有两种结果的随机试验.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Der Münzwurf ist ein Bernoulli-Experiment, bei dem bspw. das “1”-Ereignis für “Kopf” und das “0”-Ereignis für “Zahl” steht.", "fol": "S. 55", "art": "das", "dsrc": "Duden", "pl": "Bernoulli-Experimente", "n": "binom", "ns": "binom.bernoulli"}, {"t": "Standardabweichung", "zh": "标准差", "b": "prob", "d": "Wurzel aus der Varianz.", "zd": "方差的平方根.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "mathe", "q": "Die Standardabweichung ist die Wurzel aus der Varianz.", "fol": "S. 24", "vs": "Varianz", "art": "die", "dsrc": "Duden", "pl": "Standardabweichungen", "n": "binomd", "ns": "binomd.ev"}, {"t": "Informationsgehalt", "zh": "信息量", "b": "info", "d": "Negativer Logarithmus der Wahrscheinlichkeit eines Ereignisses.", "zd": "事件概率的负对数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "H(X|Y) ist die Rest-Information, die X noch liefert, wenn Y bekannt ist.", "fol": "S. 43", "vs": "Entropie", "alt": ["Information"], "art": "der", "dsrc": "Duden", "pl": "Informationsgehalte", "n": "entropy", "ns": "entropy.infoamt"}, {"t": "gemeinsame Entropie", "zh": "联合熵", "b": "info", "d": "Entropie der gemeinsamen Verteilung zweier Zufallsvariablen.", "zd": "两个随机变量联合分布的熵.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "vs": "bedingte Entropie", "art": "die", "dsrc": "Duden", "pl": "gemeinsame Entropien", "n": "condh", "ns": "condh.jent"}, {"t": "Kodierung", "zh": "编码", "b": "info", "d": "Zuordnung von Symbolen zu Bitfolgen; die Entropie ist die untere Schranke der mittleren Codelänge.", "zd": "把符号映射成比特串; 熵是平均码长的下限.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "info", "q": "Kein Code darf ein Präfix eines anderen Codes sein! (Sonst ist keine eindeutige Dekodierung möglich.)", "fol": "S. 38", "alt": ["Code"], "art": "die", "dsrc": "Duden", "pl": "Kodierungen", "n": "entropy", "ns": "entropy.code"}, {"t": "Sprachidentifizierung", "zh": "语种识别", "b": "lm", "d": "Bestimmung der Sprache eines Textes, z. B. mit einem Markowmodell pro Sprache.", "zd": "判断文本是哪种语言, 例如每种语言一个马尔可夫模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "q": "Sprachmodelle werden oft in der Sprachverarbeitung verwendet (Spracherkennung, maschinelle Übersetzung, Sprachidentifizierung).", "fol": "S. 71–73", "art": "die", "dsrc": "Duden", "pl": "Sprachidentifizierungen", "n": "markov", "ns": "markov.langid"}, {"t": "n-Gramm", "zh": "n 元组", "b": "lm", "d": "Folge von n aufeinanderfolgenden Symbolen.", "zd": "n 个相邻符号组成的序列.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "q": "Aber: Neue Texte können n-Gramme enthalten, die nicht in den Trainingsdaten auftauchten. Ihre relative Häufigkeit ist 0.", "fol": "S. 85–86", "vs": "Markowmodell", "alt": ["N-Gramm", "Bigramm", "Trigramm"], "art": "das", "dsrc": "Duden", "pl": "n-Gramme", "n": "markov", "ns": "markov.ngram"}, {"t": "Endesymbol", "zh": "结束符号", "b": "lm", "d": "Zusätzliches Symbol am Satzende, damit die Wahrscheinlichkeiten aller Folgen sich zu 1 summieren.", "zd": "句末加的符号, 让所有序列的概率之和为 1.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "q": "Wenn wir ein Endesymbol ⟨/s⟩ hinzufügen und ihm eine Wahrscheinlichkeit p(⟨/s⟩) geben, reduziert sich die Wahrscheinlichkeit p(x) zu 1 − p(⟨/s⟩).", "fol": "S. 77", "art": "das", "dsrc": "DWDS", "pl": "Endesymbole", "n": "markov", "ns": "markov.endsym"}, {"t": "Sparse-Data-Problem", "zh": "数据稀疏问题", "b": "lm", "d": "Viele mögliche Ereignisse kommen in den Trainingsdaten gar nicht oder sehr selten vor.", "zd": "很多可能的事件在训练数据里没出现或极少出现.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "markow", "alt": ["Sparse-Data Problem", "Datenspärlichkeit"], "art": "das", "dsrc": "Duden", "pl": "Sparse-Data-Probleme", "n": "sparse"}, {"t": "Add-λ Glättung", "zh": "加 λ 平滑", "b": "lm", "d": "Glättung, bei der zu jeder Häufigkeit eine Konstante λ addiert wird.", "zd": "给每个频率加常数 λ 的平滑.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "q": "Linear Discounting (Add-λ Glättung) führt zu schlechten Ergebnissen, wenn die Daten eine Zipf’sche Verteilung aufweisen.", "fol": "S. 93", "vs": "Absolute Discounting", "alt": ["Add-λ-Glättung", "Addiere-Lambda-Glättung"], "art": "die", "dsrc": "Duden", "pl": "Add-λ Glättungen", "n": "addk"}, {"t": "Laplace-Glättung", "zh": "拉普拉斯平滑", "b": "lm", "d": "Add-λ Glättung mit λ = 1.", "zd": "λ = 1 的加 λ 平滑.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "alt": ["Addiere-1-Glättung", "Add-One-Glättung"], "art": "die", "dsrc": "Duden", "pl": "Laplace-Glättungen", "n": "addk", "ns": "addk.laplace"}, {"t": "Backoff-Glättung", "zh": "回退平滑", "b": "lm", "d": "Glättung, die bei unbeobachtetem Kontext auf einen kürzeren Kontext zurückgreift.", "zd": "上下文没见过时退到更短上下文的平滑.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "q": "Berechnung der Backoff-Faktoren (interpolierte Glättung)", "fol": "S. 105", "vs": "Interpolation", "alt": ["Backoff"], "art": "die", "dsrc": "Duden", "pl": "Backoff-Glättungen", "n": "backoff"}, {"t": "Kneser-Ney-Glättung", "zh": "Kneser-Ney 平滑", "b": "lm", "d": "Backoff-Glättung, deren Backoff-Verteilung die Anzahl verschiedener Kontexte eines Wortes zählt.", "zd": "回退分布按词出现过的不同语境数来估计的平滑.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "q": "Die Kneser-Ney-Methode zählt n-Gramm-Types (statt -Tokens).", "fol": "S. 103", "vs": "Backoff-Verteilung", "alt": ["Kneser-Ney", "Kneser-Ney-Backoff"], "art": "die", "dsrc": "Duden", "pl": "Kneser-Ney-Glättungen", "n": "kn"}, {"t": "Interpolation", "zh": "插值", "b": "lm", "d": "Mischung zweier Verteilungen mit Gewichten, z. B. eines n-Gramm- und eines kürzeren Modells.", "zd": "按权重混合两个分布, 例如长短上下文模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "glaett", "q": "⇒ Interpolierte Modelle sind meistens etwas besser und die Berechnung des Backoff-Faktors ist einfacher.", "fol": "S. 98", "vs": "Backoff-Glättung", "alt": ["interpoliert"], "art": "die", "dsrc": "Duden", "pl": "Interpolationen", "n": "backoff", "ns": "backoff.interp"}, {"t": "unbekannte Wort", "zh": "未知词", "b": "tag", "d": "Wort, das in den Trainingsdaten nicht vorkommt.", "zd": "训练数据里没出现过的词.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Neben unbekannten Wörtern stellen auch ungesehene Tags bekannter Wörter ein Problem dar (bspw. wenn das englische Wort “indicate” nur als Infinitiv aber nicht als finites Verb aufgetaucht ist.)", "fol": "S. 137", "alt": ["unbekannte Wörter", "unbekanntes Wort"], "art": "das", "dsrc": "Duden", "pl": "unbekannte Wörter", "n": "unk"}, {"t": "Wortart", "zh": "词性", "b": "tag", "d": "Grammatische Kategorie eines Wortes, z. B. Nomen oder Verb.", "zd": "词的语法类别, 如名词、动词.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Weil alle Tags zusammen desambiguiert werden, beeinflusst also auch der rechte Kontext die Annotation eines Wortes.", "fol": "S. 132", "alt": ["Tag", "Wortklasse"], "art": "die", "dsrc": "Duden", "pl": "Wortarten", "n": "hmm", "ns": "hmm.posamb"}, {"t": "Wortart-Tagging", "zh": "词性标注", "b": "tag", "d": "Automatische Zuordnung einer Wortart zu jedem Wort eines Textes.", "zd": "自动给文本里每个词标上词性.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "alt": ["POS-Tagging", "Tagging"], "art": "das", "dsrc": "Duden", "pl": "Wortart-Taggings", "n": "hmm"}, {"t": "Viterbi-Wahrscheinlichkeit", "zh": "Viterbi 概率", "b": "tag", "d": "Wahrscheinlichkeit des besten Pfades, der an einer Position in einem Zustand endet.", "zd": "在某位置停在某状态的最佳路径概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Wir berechnen für jede Regel und jedes Nichtterminal der Parsewald-Grammatik eine Viterbi-Wahrscheinlichkeit.", "fol": "S. 207", "vs": "Forward-Wahrscheinlichkeit", "art": "die", "dsrc": "Duden", "pl": "Viterbi-Wahrscheinlichkeiten", "n": "viterbi", "ns": "viterbi.vdelta"}, {"t": "Forward-Wahrscheinlichkeit", "zh": "前向概率", "b": "tag", "d": "Summe der Wahrscheinlichkeiten aller Präfixe, die an einer Position in einem Tag enden.", "zd": "到某位置、停在某标签的所有前缀概率之和.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "α⟨/s⟩(6): Forward-Wahrscheinlichkeit des Ende-Tags und damit die Gesamtwk. des Satzes summiert über alle möglichen Tagfolgen.", "fol": "S. 164", "vs": "Viterbi-Wahrscheinlichkeit", "alt": ["Vorwärtswahrscheinlichkeit"], "art": "die", "dsrc": "Duden", "pl": "Forward-Wahrscheinlichkeiten", "n": "fb", "ns": "fb.alpha"}, {"t": "Backward-Wahrscheinlichkeit", "zh": "后向概率", "b": "tag", "d": "Summe der Wahrscheinlichkeiten aller Suffixe ab einer Position und einem Tag.", "zd": "从某位置某标签到句尾所有后缀的概率之和.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "alt": ["Rückwärtswahrscheinlichkeit"], "art": "die", "dsrc": "Duden", "pl": "Backward-Wahrscheinlichkeiten", "n": "fb", "ns": "fb.beta"}, {"t": "EM-Algorithmus", "zh": "EM 算法", "b": "tag", "d": "Iteratives Verfahren, das abwechselnd erwartete Häufigkeiten berechnet und Parameter neu schätzt.", "zd": "交替计算期望频率和重估参数的迭代方法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "EM passt die Parameter an die Trainingsdaten an.", "fol": "S. 220", "alt": ["EM-Training", "EM"], "art": "der", "dsrc": "Duden", "pl": "EM-Algorithmen", "n": "em"}, {"t": "E-Schritt", "zh": "E 步", "b": "tag", "d": "Schritt des EM-Algorithmus, der mit den aktuellen Parametern erwartete Häufigkeiten berechnet.", "zd": "用当前参数算期望频率的那一步.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "E-Schritt: Schätzung der erwarteten Tagpaar-Häufigkeiten f(t’,t) und Wort-Tag-Häufigkeiten f(w,t) mit dem Forward-Backward-Algorithmus", "fol": "S. 172", "vs": "M-Schritt", "art": "der", "dsrc": "Duden", "pl": "E-Schritte", "n": "em", "ns": "em.estep"}, {"t": "M-Schritt", "zh": "M 步", "b": "tag", "d": "Schritt des EM-Algorithmus, der aus den erwarteten Häufigkeiten neue Parameter schätzt.", "zd": "用期望频率重新估计参数的那一步.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "Im M-Schritt werden die Wahrscheinlichkeiten neuberechnet.", "fol": "S. 234", "vs": "E-Schritt", "art": "der", "dsrc": "Duden", "pl": "M-Schritte", "n": "em", "ns": "em.mstep"}, {"t": "lokale Maximum", "zh": "局部最大值", "b": "tag", "d": "Punkt, an dem die Zielfunktion höher ist als in der Umgebung, aber nicht unbedingt global maximal.", "zd": "比邻域都高、但不一定全局最高的点.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "alt": ["lokales Maximum"], "art": "das", "dsrc": "Duden", "pl": "lokale Maxima", "n": "em", "ns": "em.local"}, {"t": "Suffix", "zh": "后缀", "b": "tag", "d": "Wortendung; dient zur Schätzung der Wortart unbekannter Wörter.", "zd": "词尾, 用来估计未知词的词性.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "hmm", "q": "suff(w) berechnet das Suffix der festen Länge L von w. p(t|suff(w)) wird rekursiv mit Backoff geglättet.", "fol": "S. 174", "alt": ["Endung"], "art": "das", "dsrc": "Duden", "pl": "Suffixe", "n": "unk", "ns": "unk.suffix"}, {"t": "kontextfreie Grammatik", "zh": "上下文无关文法", "b": "parse", "d": "Grammatik, deren Regeln links genau ein Nichtterminalsymbol haben.", "zd": "规则左部只有一个非终结符的文法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Eine kontextfreie Grammatik ist gegeben.", "fol": "S. 199", "alt": ["CFG"], "art": "die", "dsrc": "Duden", "pl": "kontextfreie Grammatiken", "n": "pcfg", "ns": "pcfg.cfg"}, {"t": "probabilistische kontextfreie Grammatik", "zh": "概率上下文无关文法", "b": "parse", "d": "Kontextfreie Grammatik, deren Regeln Wahrscheinlichkeiten tragen.", "zd": "规则带概率的上下文无关文法.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "PCFG = CFG + Regelwahrscheinlichkeiten", "fol": "S. 186", "alt": ["PCFG"], "art": "die", "dsrc": "Duden", "pl": "probabilistische kontextfreie Grammatiken", "n": "pcfg"}, {"t": "Ableitung", "zh": "推导", "b": "parse", "d": "Folge von Regelanwendungen vom Startsymbol bis zum Satz.", "zd": "从起始符号到句子的一串规则应用.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Folge der partiellen Parsebäume für die Ableitung", "fol": "S. 181", "vs": "Linksableitung", "art": "die", "dsrc": "Duden", "pl": "Ableitungen", "n": "pcfg", "ns": "pcfg.deriv"}, {"t": "Parsebaum", "zh": "分析树", "b": "parse", "d": "Baum, der die syntaktische Struktur eines Satzes darstellt.", "zd": "表示句子句法结构的树.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Für jeden kontextfreien Parsebaum gibt es genau eine Linksableitung und umgekehrt.", "fol": "S. 182", "vs": "Parsewald", "alt": ["Syntaxbaum", "Analysebaum"], "art": "der", "dsrc": "DWDS", "pl": "Parsebäume", "n": "pcfg"}, {"t": "syntaktische Ambiguität", "zh": "句法歧义", "b": "parse", "d": "Ein Satz hat mehrere mögliche syntaktische Analysen.", "zd": "一个句子有多种可能的句法分析.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "alt": ["strukturelle Ambiguität"], "art": "die", "dsrc": "Duden", "pl": "syntaktische Ambiguitäten", "n": "pcfg", "ns": "pcfg.synamb"}, {"t": "Baumbank-Training", "zh": "树库训练", "b": "parse", "d": "Schätzung der Regelwahrscheinlichkeiten als relative Häufigkeiten in einer Baumbank.", "zd": "用树库里规则的相对频率估计规则概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Wenn eine genügend große Baumbank verfügbar ist, liefert das Baumbank-Training bessere Ergebnisse als EM-Training.", "fol": "S. 220", "art": "das", "dsrc": "Duden", "pl": "Baumbank-Trainings", "n": "treebank"}, {"t": "Inside-Wahrscheinlichkeit", "zh": "Inside 概率", "b": "parse", "d": "Gesamtwahrscheinlichkeit aller Teilbäume unterhalb eines Knotens im Parsewald.", "zd": "分析森林里一个节点下所有子树的总概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Die Inside-Wahrscheinlichkeiten α(.) wurden schon berechnet. Die Regelwahrscheinlichkeiten p(S → NP VP) etc. sind gegeben. Die Outside-Wahrscheinlichkeiten β(.) werden top-down berechnet.", "fol": "S. 214", "vs": "Outside-Wahrscheinlichkeit", "art": "die", "dsrc": "Duden", "pl": "Inside-Wahrscheinlichkeiten", "n": "io", "ns": "io.inside"}, {"t": "Outside-Wahrscheinlichkeit", "zh": "Outside 概率", "b": "parse", "d": "Gesamtwahrscheinlichkeit des Teils des Baumes außerhalb eines Knotens.", "zd": "节点之外部分的总概率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Aus den Inside- und Outside-Wahrscheinlichkeiten berechnet er die erwarteten Häufigkeiten.", "fol": "S. 210", "vs": "Inside-Wahrscheinlichkeit", "art": "die", "dsrc": "Duden", "pl": "Outside-Wahrscheinlichkeiten", "n": "io", "ns": "io.outside"}, {"t": "Inside-Outside-Algorithmus", "zh": "Inside-Outside 算法", "b": "parse", "d": "Berechnet erwartete Regelhäufigkeiten einer PCFG für das EM-Training.", "zd": "为 EM 训练计算 PCFG 的期望规则频率.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "q": "Lösung: Inside-Outside-Algorithmus (wird später vorgestellt)", "fol": "S. 195", "vs": "Forward-Backward-Algorithmus", "art": "der", "dsrc": "Duden", "pl": "Inside-Outside-Algorithmen", "n": "io"}, {"t": "Berkeley-Parser", "zh": "Berkeley 分析器", "b": "parse", "d": "Parser, der verfeinerte Kategorien durch Aufspalten, EM-Training und Vereinigen automatisch lernt.", "zd": "靠分裂、EM 训练、合并自动学习细化范畴的分析器.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "berkeley", "art": "der", "dsrc": "Duden", "pl": "Berkeley-Parser", "n": "berkeley"}, {"t": "Merkmal", "zh": "特征", "b": "disc", "d": "Funktion, die eine Eigenschaft der Eingabe (und der Klasse) als Zahl ausdrückt.", "zd": "把输入 (和类别) 的某种性质表示成数值的函数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "q": "Die Gewichte aller Merkmale, deren Wert von 0 verschieden ist, fließen in die Klassifikation ein.", "fol": "S. 264", "vs": "Merkmalsfunktion", "alt": ["Feature"], "art": "das", "dsrc": "Duden", "pl": "Merkmale", "n": "generative", "ns": "generative.feat"}, {"t": "Gewicht", "zh": "权重", "b": "disc", "d": "Parameter, mit dem ein Merkmal in den Score eingeht.", "zd": "特征进入分数时乘的参数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "q": "Die Gewichte aller Merkmale, deren Wert von 0 verschieden ist, fließen in die Klassifikation ein.", "fol": "S. 264", "art": "das", "dsrc": "Duden", "pl": "Gewichte", "n": "linclf", "ns": "linclf.fvec"}, {"t": "Merkmalsvektor", "zh": "特征向量", "b": "disc", "d": "Vektor der Werte aller Merkmale für eine Eingabe.", "zd": "一个输入所有特征取值组成的向量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "q": "Merkmalsvektoren und Gewichtsvektoren enthalten für jedes Merkmal einen Wert.", "fol": "S. 267", "alt": ["Featurevektor"], "art": "der", "dsrc": "DWDS", "pl": "Merkmalsvektoren", "n": "linclf", "ns": "linclf.fvec"}, {"t": "lineare Klassifikator", "zh": "线性分类器", "b": "disc", "d": "Klassifikator, der die Klasse mit dem höchsten gewichteten Merkmalsscore wählt.", "zd": "选加权特征分数最高的类别的分类器.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "diskr", "alt": ["linearer Klassifikator"], "art": "der", "dsrc": "Duden", "pl": "lineare Klassifikatoren", "n": "linclf"}, {"t": "Normierung", "zh": "归一化", "b": "disc", "d": "Division durch die Summe über alle Klassen, damit Wahrscheinlichkeiten sich zu 1 summieren.", "zd": "除以所有类的总和, 让概率之和为 1.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "alt": ["Normierungskonstante"], "art": "die", "dsrc": "Duden", "pl": "Normierungen", "n": "loglin", "ns": "loglin.norm"}, {"t": "Gradient", "zh": "梯度", "b": "disc", "d": "Vektor der partiellen Ableitungen einer Funktion.", "zd": "函数各偏导数组成的向量.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "q": "Der Gradient wird mit der Lernrate multipliziert und zum Gewichtsvektor addiert. (Gradientenanstieg)", "fol": "S. 305", "art": "der", "dsrc": "Duden", "pl": "Gradienten", "n": "grad"}, {"t": "partielle Ableitung", "zh": "偏导数", "b": "disc", "d": "Ableitung einer Funktion nach einer einzelnen Variablen.", "zd": "函数对单个变量的导数.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "vs": "Gradient", "art": "die", "dsrc": "Duden", "pl": "partielle Ableitungen", "n": "loglin", "ns": "loglin.deriv"}, {"t": "Lernrate", "zh": "学习率", "b": "disc", "d": "Schrittweite beim Gradientenanstieg.", "zd": "梯度上升每一步的步长.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "q": "Die Lernrate η bestimmt, wie groß die einzelnen Schritte sind. Wenn eine Funktion minimiert werden muss, spricht man von Gradientenabstieg. Dann wird der Gradient ∇f(θ) subtrahiert.", "fol": "S. 289", "art": "die", "dsrc": "课件", "n": "grad", "ns": "grad.lr"}, {"t": "stochastische Gradientenanstieg", "zh": "随机梯度上升", "b": "disc", "d": "Gradientenanstieg, der nach jedem einzelnen Trainingsbeispiel die Gewichte aktualisiert.", "zd": "每个训练样本之后就更新权重的梯度上升.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "loglin", "alt": ["SGD", "stochastischer Gradientenanstieg"], "art": "der", "dsrc": "DWDS", "n": "grad", "ns": "grad.sgd"}, {"t": "Conditional Random Field", "zh": "条件随机场", "b": "disc", "d": "Log-lineares Modell über ganze Tagfolgen.", "zd": "定义在整个标签序列上的对数线性模型.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "crf", "q": "Das Training von CRFs ist iterativ.", "fol": "S. 305", "vs": "Hidden-Markow-Modell", "alt": ["CRF", "Linear-Chain CRF"], "n": "crf"}, {"t": "Trainingsdaten", "zh": "训练数据", "b": "eval", "d": "Daten, aus denen die Modellparameter geschätzt werden.", "zd": "用来估计模型参数的数据.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "q": "Wenn die Trainingsdaten linear separierbar sind, findet der Algorithmus in endlicher Zeit einen Gewichtsvektor, der alle Daten richtig klassifiziert.", "fol": "S. 272", "vs": "Testdaten", "n": "gold"}, {"t": "Testdaten", "zh": "测试数据", "b": "eval", "d": "Daten, die beim Training nicht verwendet werden und zur Evaluierung dienen.", "zd": "训练时不用、专门用来评估的数据.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "tests", "q": "In der Regel braucht man für Experimente in der Computerlinguistik Trainingsdaten, Developmentdaten und Testdaten.", "fol": "S. 152", "vs": "Entwicklungsdaten", "n": "gold"}, {"t": "F-Score", "zh": "F 值", "b": "eval", "d": "Harmonisches Mittel von Precision und Recall.", "zd": "精确率和召回率的调和平均.", "f": "SMIS-合集-语言处理中的统计方法.html", "a": "pcfg", "alt": ["F-Maß", "F1"], "art": "der", "dsrc": "Duden", "pl": "F-Scores", "n": "prf"}], "newf": []});